# llama-cpp-log-monitor.ps1 — Updated for router mode + progress lines
param(
    [string]$LogPath = "",
    [int]$RefreshMs = 500
)

$logDir = "C:\llama.cpp-prod\logs"

if ($LogPath -eq "") {
    $latestLog = Get-ChildItem -Path $logDir -Filter "server_*.log" | Sort-Object LastWriteTime -Descending | Select-Object -First 1
    if ($latestLog) {
        $LogPath = $latestLog.FullName
        Write-Host "Found log: $LogPath" -ForegroundColor Green
    } else {
        Write-Host "No log found" -ForegroundColor Red; exit 1
    }
}

# ---------- regex patterns (un-anchored — lines have [PID] prefixes now) ----------

# Strip the log prefix before matching: optional [PID], timestamp, facility, and "id N | task N |"
$patternPrefix = '^(?:\[\d+\]\s*)?[\d.]+ [A-Za-z] \w+\s+\S+:\s*(?:id\s+\d+\s*\|\s*task\s+\d+\s*\|\s*)?'

# Core timing patterns — these search the cleaned portion of each line
$patternPrompt  = 'prompt eval time\s*=\s*([\d.]+)\s*ms\s*/\s*(\d+)\s*tokens?\s*\(\s*([\d.]+)\s*ms per token,\s*([\d.]+)\s*tokens per second\)'
$patternEval    = '(?<!prompt )eval time\s*=\s*([\d.]+)\s*ms\s*/\s*(\d+)\s*tokens?\s*\(\s*([\d.]+)\s*ms per token,\s*([\d.]+)\s*tokens per second\)'
$patternTotal   = 'total time\s*=\s*([\d.]+)\s*ms\s*/\s*(\d+)\s*tokens?'
$patternDraft   = 'draft acceptance\s*=\s*([\d.]+)'
$patternRelease = 'stop processing:\s*n_tokens\s*=\s*(\d+)'
$patternGraphs  = 'graphs reused\s*=\s*(\d+)'

# New: real-time generation progress lines
#   n_decoded =    184, tg =  61.13 t/s, tg_3s =  61.13 t/s
$patternProgress = 'n_decoded\s*=\s*(\d+),\s*tg\s*=\s*([\d.]+)\s*t/s'

# ---------- state ----------

$lastSize = (Get-Item $LogPath).Length
$history = [System.Collections.ArrayList]::new()
$maxHistory = 30
$requestCount = 0

$current = @{
    PromptTps   = 0;  PromptTok   = 0
    EvalTps     = 0;  EvalTok     = 0
    TotalTps    = 0;  TotalTok    = 0
    DraftPct    = 0
    Context     = 0
    GraphsReuse = 0
    HasPrompt   = $false
    HasEval     = $false
    LiveTg      = 0      # most recent tg (tokens/sec during generation)
    LiveTokens  = 0      # most recent n_decoded
}

function Show-Dashboard {
    param($Current)

    Clear-Host
    $header = "llama.cpp prod Performance Monitor"
    $ts = Get-Date -Format "yyyy-MM-dd HH:mm:ss"
    Write-Host "  $header  |  Request #$requestCount  |  $ts" -ForegroundColor Cyan
    Write-Host ("  " + ("=" * 110)) -ForegroundColor Cyan

    Write-Host ""
    Write-Host "    CURRENT REQUEST                                      SESSION SUMMARY ($($history.Count) requests)"
    Write-Host "    ---------------                                      ------------------------------"

    $avgP = if ($history.Count -gt 0) { [math]::Round((($history | Measure-Object PromptTps -Average).Average),1) } else { 0 }
    $avgE = if ($history.Count -gt 0) { [math]::Round((($history | Measure-Object EvalTps -Average).Average),1) } else { 0 }
    $avgT = if ($history.Count -gt 0) { [math]::Round((($history | Measure-Object TotalTps -Average).Average),1) } else { 0 }
    $maxP = if ($history.Count -gt 0) { [math]::Round((($history | Measure-Object PromptTps -Maximum).Maximum),1) } else { 0 }
    $maxE = if ($history.Count -gt 0) { [math]::Round((($history | Measure-Object EvalTps -Maximum).Maximum),1) } else { 0 }

    $left1 = "    Prompt:  $([math]::Round($Current.PromptTps,1)) tok/s ($($Current.PromptTok) tokens)"
    $left2 = "    Output:  $([math]::Round($Current.EvalTps,1)) tok/s ($($Current.EvalTok) tokens)"
    $left3 = "    Total:   $([math]::Round($Current.TotalTps,1)) tok/s"
    $liveTg = if ($Current.LiveTg -gt 0) { "$([math]::Round($Current.LiveTg,1)) t/s ($($Current.LiveTokens) tok)" } else { "waiting..." }
    $left25 = "    Live tg: $liveTg"
    $left4 = "    Draft:   $(if ($Current.DraftPct -gt 0) { "$([math]::Round($Current.DraftPct*100,1))%" } else { "N/A" })"
    $left5 = "    Graphs:  $(if ($Current.GraphsReuse -gt 0) { $Current.GraphsReuse } else { "N/A" })"

    $pad = 55

    Write-Host (Pad-Right $left1 $pad)  "Avg prompt:  $avgP tok/s"
    Write-Host (Pad-Right $left2 $pad)  "Avg output:  $avgE tok/s"
    Write-Host (Pad-Right $left3 $pad)  "Avg total:   $avgT tok/s"
    Write-Host (Pad-Right $left25 $pad) "Peak prompt: $maxP tok/s"
    Write-Host (Pad-Right $left4 $pad)  "Peak output: $maxE tok/s"
    Write-Host (Pad-Right $left5 $pad)  ""

    Write-Host "`n    RECENT REQUESTS (last $($history.Count))"
    Write-Host "     #   Prompt    P-t/s   Eval    E-t/s   Total-t/s   Draft    Graphs   Context"
    Write-Host "     --  ------   ------   -----   ------  ---------   ------   ------   ---------"

    $i = 1
    foreach ($h in $history) {
        $draftStr = if ($h.DraftPct -gt 0) { "$([math]::Round($h.DraftPct*100,1))%" } else { "N/A" }
        $graphStr = if ($h.GraphsReuse -gt 0) { $h.GraphsReuse.ToString("N0") } else { "" }
        $ctx = if ($h.Context) { $h.Context.ToString("N0") } else { "" }
        $line = "     {0,-3}  {1,-6}  {2,6}  {3,-5}  {4,6}  {5,9}   {6,-6}   {7,-6}   {8}" -f
                $i, $h.PromptTok, [math]::Round($h.PromptTps,1), $h.EvalTok,
                [math]::Round($h.EvalTps,1), [math]::Round($h.TotalTps,1), $draftStr, $graphStr, $ctx
        Write-Host $line
        $i++
    }

    Write-Host "`n  Waiting for next request... (Ctrl+C to stop)" -ForegroundColor DarkGray
}

function Pad-Right {
    param([string]$Text, [int]$Width = 55)
    if ($Text.Length -ge $Width) { return $Text.Substring(0, $Width) }
    return $Text + (" " * ($Width - $Text.Length))
}

# strip log prefix to get the clean message body for regex matching
function Get-CleanLine {
    param([string]$Line)
    # Remove leading [PID] if present, then the timestamp + facility + function prefix
    $clean = $Line -replace '^\[\d+\]\s*', ''
    # Remove "id N | task N |" prefix from slot lines
    $clean = $clean -replace '^[\d.]+ [A-Za-z] \w+\s+\S+:\s*(?:id\s+\d+\s*\|\s*task\s+\d+\s*\|\s*)?', ''
    return $clean
}

# ---------- main loop ----------

$running = $true
[Console]::TreatControlCAsInput = $true

while ($running) {
    try {
        if ([Console]::KeyAvailable) {
            $key = [Console]::ReadKey($true)
            if ($key.Key -eq "C" -and $key.Modifiers -eq "Control") { $running = $false; break }
        }

        # detect log rotation
        if (Test-Path $logDir) {
            $latest = Get-ChildItem -Path $logDir -Filter "server_*.log" | Sort-Object LastWriteTime -Descending | Select-Object -First 1
            if ($latest -and $latest.FullName -ne $LogPath) {
                Write-Host "  Log rotated: $($latest.Name)" -ForegroundColor Yellow
                $LogPath = $latest.FullName
                $lastSize = 0
                $current = @{PromptTps=0; PromptTok=0; EvalTps=0; EvalTok=0; TotalTps=0; TotalTok=0; DraftPct=0; Context=0; GraphsReuse=0; HasPrompt=$false; HasEval=$false; LiveTg=0; LiveTokens=0}
            }
        }

        $fileInfo = Get-Item $LogPath -ErrorAction SilentlyContinue
        if (-not $fileInfo) { Start-Sleep -Milliseconds $RefreshMs; continue }

        $currentSize = $fileInfo.Length
        if ($currentSize -eq $lastSize) { Start-Sleep -Milliseconds $RefreshMs; continue }

        # read new content
        $stream = [System.IO.FileStream]::new($LogPath, 'Open', 'Read', 'ReadWrite')
        $stream.Seek($lastSize, 'Begin') | Out-Null
        $newContent = [System.IO.StreamReader]::new($stream).ReadToEnd()
        $stream.Close()
        $lastSize = $currentSize

        $hadUpdate = $false

        foreach ($rawLine in ($newContent -split "`n")) {
            $rawLine = $rawLine.Trim()
            if ($rawLine -eq "") { continue }

            # Work with the clean line (prefix stripped) for matching
            $line = Get-CleanLine $rawLine
            if ($line -eq "") { continue }

            # --- real-time generation progress (NEW) ---
            if ($line -match $patternProgress) {
                $current.LiveTokens = [int]$Matches[1]
                $current.LiveTg      = [double]$Matches[2]
                $hadUpdate = $true
                continue
            }

            # --- prompt eval ---
            if ($line -match $patternPrompt) {
                $current.PromptTok = [int]$Matches[2]
                $current.PromptTps = [double]$Matches[4]
                $current.HasPrompt = $true
                continue
            }

            # --- eval time (negative lookbehind prevents matching "prompt eval time") ---
            if ($line -match $patternEval) {
                $current.EvalTok = [int]$Matches[2]
                $current.EvalTps = [double]$Matches[4]
                $current.HasEval = $true
                continue
            }

            # --- total time ---
            if ($line -match $patternTotal) {
                $current.TotalTok = [int]$Matches[2]
                $ms = [double]$Matches[1]
                $current.TotalTps = if ($ms -gt 0) { $current.TotalTok / ($ms / 1000) } else { 0 }
                continue
            }

            # --- draft acceptance ---
            if ($line -match $patternDraft) {
                $current.DraftPct = [double]$Matches[1]
                continue
            }

            # --- graphs reused ---
            if ($line -match $patternGraphs) {
                $current.GraphsReuse = [int]$Matches[1]
                continue
            }

            # --- release / end of request ---
            if ($line -match $patternRelease) {
                $current.Context = [int]$Matches[1]

                if ($current.HasPrompt -and $current.HasEval) {
                    $requestCount++
                    $entry = [PSCustomObject]@{
                        PromptTok   = $current.PromptTok
                        PromptTps   = $current.PromptTps
                        EvalTok     = $current.EvalTok
                        EvalTps     = $current.EvalTps
                        TotalTps    = $current.TotalTps
                        DraftPct    = $current.DraftPct
                        Context     = $current.Context
                        GraphsReuse = $current.GraphsReuse
                    }
                    $history.Add($entry) | Out-Null
                    if ($history.Count -gt $maxHistory) { $history.RemoveAt(0) }

                    Show-Dashboard -Current $current
                    $hadUpdate = $false

                    $current = @{
                        PromptTps=0; PromptTok=0; EvalTps=0; EvalTok=0
                        TotalTps=0; TotalTok=0; DraftPct=0; Context=0; GraphsReuse=0
                        HasPrompt=$false; HasEval=$false; LiveTg=0; LiveTokens=0
                    }
                }
            }
        }

        # If we got progress updates but no completion, refresh the dashboard
        if ($hadUpdate -and $current.LiveTg -gt 0) {
            Show-Dashboard -Current $current
        }
    }
    catch { Write-Host "Error: $_" -ForegroundColor Red }
    Start-Sleep -Milliseconds $RefreshMs
}

# llama-cpp-log-monitor.ps1 — Updated for router mode + live tg progress
param(
