    Write-Host (Pad-Right $left6 $pad) ""

    Write-Host "`n    RECENT REQUESTS (last $($history.Count))"
    Write-Host "     #   Prompt   P-t/s   Eval    E-t/s   Total-t/s   Draft    Graphs   Context"
    Write-Host "     --  ------   ------  -----   ------  ---------   ------   ------   ---------"

    $i = 1
    foreach ($h in $history) {
        $draftStr = if ($h.DraftPct -gt 0) { "$([math]::Round($h.DraftPct*100,1))%" } else { "N/A" }
        $graphStr = if ($h.GraphsReuse -gt 0) { $h.GraphsReuse.ToString("N0") } else { "" }
        $ctx = if ($h.Context) { $h.Context.ToString("N0") } else { "" }
        $line = "     {0,-3}  {1,-6}  {2,6}  {3,-5}  {4,6}  {5,9}   {6,-6}   {7,-6}   {8}" -f
                $i, $h.PromptTok, [math]::Round($h.PromptTps,1), $h.EvalTok,
                [math]::Round($h.EvalTps,1), [math]::Round($h.TotalTps,1), $draftStr, $graphStr, $ctx
        Write-Host $line
        $i++
    }

    Write-Host "`n  Waiting for next request... (Ctrl+C to stop)" -ForegroundColor DarkGray
}

function Pad-Right {
    param([string]$Text, [int]$Width = 55)
    if ($Text.Length -ge $Width) { return $Text.Substring(0, $Width) }
    return $Text + (" " * ($Width - $Text.Length))
}

# ---------- main loop ----------
$running = $true
[Console]::TreatControlCAsInput = $true

while ($running) {
    try {
        if ([Console]::KeyAvailable) {
            $key = [Console]::ReadKey($true)
            if ($key.Key -eq "C" -and $key.Modifiers -eq "Control") { $running = $false; break }
        }

        # detect log rotation
        if (Test-Path $logDir) {
            $latest = Get-ChildItem -Path $logDir -Filter "server_*.log" | Sort-Object LastWriteTime -Descending | Select-Object -First 1
            if ($latest -and $latest.FullName -ne $LogPath) {
                Write-Host "  Log rotated: $($latest.Name)" -ForegroundColor Yellow
                $LogPath = $latest.FullName
                $lastSize = 0
                $current = @{PromptTps=0; PromptTok=0; EvalTps=0; EvalTok=0; TotalTps=0; TotalTok=0; DraftPct=0; Context=0; GraphsReuse=0; HasPrompt=$false; HasEval=$false; LiveTg=0; LiveTokens=0}
            }
        }

        $fileInfo = Get-Item $LogPath -ErrorAction SilentlyContinue
        if (-not $fileInfo) { Start-Sleep -Milliseconds $RefreshMs; continue }

        $currentSize = $fileInfo.Length
        if ($currentSize -eq $lastSize) { Start-Sleep -Milliseconds $RefreshMs; continue }

        # read new content
        $stream = [System.IO.FileStream]::new($LogPath, 'Open', 'Read', 'ReadWrite')
        $stream.Seek($lastSize, 'Begin') | Out-Null
        $newContent = [System.IO.StreamReader]::new($stream).ReadToEnd()
        $stream.Close()
        $lastSize = $currentSize

        $hadProgress = $false

        foreach ($rawLine in ($newContent -split "`n")) {
            $rawLine = $rawLine.Trim()
            if ($rawLine -eq "") { continue }

            # Strip the [PID] + timestamp + facility prefix for clean matching
            $line = Get-CleanLine $rawLine
            if ($line -eq "") { continue }

            # --- real-time generation progress (NEW in router mode) ---
            if ($line -match $patternProgress) {
                $current.LiveTokens = [int]$Matches[1]
                $current.LiveTg      = [double]$Matches[2]
                $hadProgress = $true
                continue
            }

            # --- prompt eval ---
            if ($line -match $patternPrompt) {
                $current.PromptTok = [int]$Matches[2]
                $current.PromptTps = [double]$Matches[4]
                $current.HasPrompt = $true
                continue
            }

            # --- eval time (negative lookbehind prevents matching "prompt eval time") ---
            if ($line -match $patternEval) {
                $current.EvalTok = [int]$Matches[2]
                $current.EvalTps = [double]$Matches[4]
                $current.HasEval = $true
                continue
            }

            # --- total time ---
            if ($line -match $patternTotal) {
                $current.TotalTok = [int]$Matches[2]
                $ms = [double]$Matches[1]
                $current.TotalTps = if ($ms -gt 0) { $current.TotalTok / ($ms / 1000) } else { 0 }
                continue
            }

            # --- draft acceptance ---
            if ($line -match $patternDraft) {
                $current.DraftPct = [double]$Matches[1]
                continue
            }

            # --- graphs reused ---
            if ($line -match $patternGraphs) {
                $current.GraphsReuse = [int]$Matches[1]
                continue
            }

            # --- release / end of request ---
            if ($line -match $patternRelease) {
                $current.Context = [int]$Matches[1]

                if ($current.HasPrompt -and $current.HasEval) {
                    $requestCount++
                    $entry = [PSCustomObject]@{
                        PromptTok   = $current.PromptTok
                        PromptTps   = $current.PromptTps
                        EvalTok     = $current.EvalTok
                        EvalTps     = $current.EvalTps
                        TotalTps    = $current.TotalTps
                        DraftPct    = $current.DraftPct
                        Context     = $current.Context
                        GraphsReuse = $current.GraphsReuse
                    }
                    $history.Add($entry) | Out-Null
                    if ($history.Count -gt $maxHistory) { $history.RemoveAt(0) }

                    Show-Dashboard -Current $current

                    $current = @{
                        PromptTps=0; PromptTok=0; EvalTps=0; EvalTok=0
                        TotalTps=0; TotalTok=0; DraftPct=0; Context=0; GraphsReuse=0
                        HasPrompt=$false; HasEval=$false; LiveTg=0; LiveTokens=0
                    }
                    $hadProgress = $false
                }
            }
        }

        # If we saw progress lines but no completion yet, refresh dashboard to show live tg
        if ($hadProgress) {
            Show-Dashboard -Current $current
        }
    }
    catch { Write-Host "Error: $_" -ForegroundColor Red }
    Start-Sleep -Milliseconds $RefreshMs
}

