cd "C:\Users\johnk\OneDrive\Documents\Claude\Projects\TPS Monitor" && powershell -NoProfile -Command "
\$logFile = '.\B70-server_2026-06-29_060355.log'

# Same patterns as the script
\$patPrompt  = 'prompt eval time\s*=\s*([\d.]+)\s*ms\s*/\s*(\d+)\s*tokens?\s*\(\s*([\d.]+)\s*ms per token,\s*([\d.]+)\s*tokens per second\)'
\$patEval    = '(?<!prompt )eval time\s*=\s*([\d.]+)\s*ms\s*/\s*(\d+)\s*tokens?\s*\(\s*([\d.]+)\s*ms per token,\s*([\d.]+)\s*tokens per second\)'
\$patTotal   = 'total time\s*=\s*([\d.]+)\s*ms\s*/\s*(\d+)\s*tokens?'
\$patDraft   = 'draft acceptance\s*=\s*([\d.]+)'
\$patGraphs  = 'graphs reused\s*=\s*(\d+)'
\$patRelease = 'stop processing:\s*n_tokens\s*=\s*(\d+)'
\$patProgress = 'n_decoded\s*=\s*(\d+),\s*tg\s*=\s*([\d.]+)\s*t/s'

function Get-CleanLine(\$Line) {
    \$clean = \$Line -replace '^\[\d+\]\s*', ''
    \$clean = \$clean -replace '^[\d.]+ [A-Z] \w+\s+\S+:\s*(?:id\s+\d+\s*\|\s*task\s+\d+\s*\|\s*)?', ''
    return \$clean
}

\$content = Get-Content \$logFile
\$requestCount = 0
\$current = @{PromptTps=0; PromptTok=0; EvalTps=0; EvalTok=0; TotalTps=0; TotalTok=0; DraftPct=0; Context=0; GraphsReuse=0; HasPrompt=\$false; HasEval=\$false; LiveTg=0; LiveTokens=0}
\$records = @()

foreach (\$rawLine in \$content) {
    \$rawLine = \$rawLine.Trim()
    if (\$rawLine -eq '') { continue }
    \$line = Get-CleanLine \$rawLine
    if (\$line -eq '') { continue }

    if (\$line -match \$patProgress) {
        \$current.LiveTokens = [int]\$Matches[1]
        \$current.LiveTg      = [double]\$Matches[2]
        continue
    }
    if (\$line -match \$patPrompt) {
        \$current.PromptTok = [int]\$Matches[2]
        \$current.PromptTps = [double]\$Matches[4]
        \$current.HasPrompt = \$true
        continue
    }
    if (\$line -match \$patEval) {
        \$current.EvalTok = [int]\$Matches[2]
        \$current.EvalTps = [double]\$Matches[4]
        \$current.HasEval = \$true
        continue
    }
    if (\$line -match \$patTotal) {
        \$current.TotalTok = [int]\$Matches[2]
        \$ms = [double]\$Matches[1]
        \$current.TotalTps = if (\$ms -gt 0) { \$current.TotalTok / (\$ms / 1000) } else { 0 }
        continue
    }
    if (\$line -match \$patDraft) {
        \$current.DraftPct = [double]\$Matches[1]
        continue
    }
    if (\$line -match \$patGraphs) {
        \$current.GraphsReuse = [int]\$Matches[1]
        continue
    }
    if (\$line -match \$patRelease) {
        \$current.Context = [int]\$Matches[1]
        if (\$current.HasPrompt -and \$current.HasEval) {
            \$requestCount++
            \$record = [PSCustomObject]@{
                ReqNum      = \$requestCount
                PromptTok   = \$current.PromptTok
                PromptTps   = [math]::Round(\$current.PromptTps, 1)
                EvalTok     = \$current.EvalTok
                EvalTps     = [math]::Round(\$current.EvalTps, 1)
                TotalTps    = [math]::Round(\$current.TotalTps, 1)
                TotalTok    = \$current.TotalTok
                DraftPct    = [math]::Round(\$current.DraftPct * 100, 1)
                GraphsReuse = \$current.GraphsReuse
                Context     = \$current.Context
            }
            \$records += \$record
            Write-Host \"Request #\$requestCount captured: prompt=\$(\$current.PromptTok)tok @ \$([math]::Round(\$current.PromptTps,1))t/s | eval=\$(\$current.EvalTok)tok @ \$([math]::Round(\$current.EvalTps,1))t/s | total=\$([math]::Round(\$current.TotalTps,1))t/s | draft=\$([math]::Round(\$current.DraftPct*100,1))% | graphs=\$(\$current.GraphsReuse)\" -ForegroundColor Green
        } else {
            Write-Host \"WARNING: Release seen but HasPrompt=\$(\$current.HasPrompt) HasEval=\$(\$current.HasEval)\" -ForegroundColor Yellow
        }
        \$current = @{PromptTps=0; PromptTok=0; EvalTps=0; EvalTok=0; TotalTps=0; TotalTok=0; DraftPct=0; Context=0; GraphsReuse=0; HasPrompt=\$false; HasEval=\$false; LiveTg=0; LiveTokens=0}
    }
}

Write-Host ''
Write-Host \"=== SUMMARY: \$requestCount requests parsed ===\" -ForegroundColor Cyan
\$records | Format-Table ReqNum, PromptTok, PromptTps, EvalTok, EvalTps, TotalTps, TotalTok, DraftPct, GraphsReuse, Context -AutoSize
"

