        # If we saw progress lines but no completion yet, refresh dashboard to show live tg
        if ($hadProgress) {
            Show-Dashboard -Current $current
        }
    }
    catch { Write-Host "Error: $_" -ForegroundColor Red }
    Start-Sleep -Milliseconds $RefreshMs
