# llama-cpp-log-monitor.ps1 - Updated for Router/PID Log Syntax
param(
    [string]$LogPath = "",
    [int]$RefreshMs = 500
)

$logDir = "C:\llama.cpp-prod\logs"

if ($LogPath -eq "") {
    $latestLog = Get-ChildItem -Path $logDir -Filter "*server_*.log" | Sort-Object LastWriteTime -Descending | Select-Object -First 1
    if ($latestLog) {
        $LogPath = $latestLog.FullName
        Write-Host "Found log: $LogPath" -ForegroundColor Green
    } else {
        Write-Host "No log found" -ForegroundColor Red; exit 1
    }
}

# ---------- Regex patterns (un-anchored; applied after prefix stripping) ----------
$patternPrompt     = 'prompt eval time\s*=\s*([\d.]+)\s*ms\s*/\s*(\d+)\s*tokens?\s*\(\s*([\d.]+)\s*ms per token,\s*([\d.]+)\s*tokens per second\)'
$patternEval       = 'eval time\s*=\s*([\d.]+)\s*ms\s*/\s*(\d+)\s*tokens?\s*\(\s*([\d.]+)\s*ms per token,\s*([\d.]+)\s*tokens per second\)'
$patternTotal      = 'total time\s*=\s*([\d.]+)\s*ms\s*/\s*(\d+)\s*tokens?'
$patternDraft      = 'draft acceptance\s*=\s*([\d.]+)'
$patternRelease    = 'stop processing:\s*n_tokens\s*=\s*(\d+)'
$patternGraphs     = 'graphs reused\s*=\s*(\d+)'
# NEW: real-time generation progress
$patternProgress   = 'n_decoded\s*=\s*(\d+),\s*tg\s*=\s*([\d.]+)\s*t/s'
# NEW: prompt processing progress (long prompt evals)
$patternPromptProg = 'prompt processing,\s*n_tokens\s*=\s*(\d+),\s*progress\s*=\s*([\d.]+),\s*t\s*=\s*([\d.]+)\s*s\s*/\s*([\d.]+)\s*tokens per second'

# ---------- helper: strip [PID] + timestamp + facility + source function: + id|task| ----------
function Get-CleanLine {
    param([string]$Line)
    # 1. Strip [PID] prefix if present  e.g. "[65225] "
    $clean = $Line -replace '^\[\d+\]\s*', ''
    # 2. Strip timestamp facility source function: and optional "id N | task N |"
    #    Format: <timestamp> <facility> <source> <function>: [id N | task N |] <message>
    #    Uses [^:]+ to match the function name (may include underscores, parens)
    $clean = $clean -replace '^[\d.]+\s+[A-Z]\s+\w+\s+[^:]+\:\s*(?:id\s+\d+\s*\|\s*task\s+-?\d+\s*\|\s*)?', ''
    return $clean
}

# ---------- state ----------
$lastSize = (Get-Item $LogPath).Length
$history = [System.Collections.ArrayList]::new()
$maxHistory = 20
$requestCount = 0

$current = @{
    PromptTps      = 0;  PromptTok      = 0
    EvalTps        = 0;  EvalTok        = 0
    TotalTps       = 0;  TotalTok       = 0
    DraftPct       = 0
    Context        = 0
    GraphsReuse    = 0
    HasPrompt      = $false
    HasEval        = $false
    LiveTg         = 0       # latest tg (tokens/sec during generation)
    LiveTokens     = 0       # latest n_decoded count
    PromptProgPct  = 0       # prompt processing progress (0.0 - 1.0)
    PromptProgTps  = 0       # prompt processing current t/s
}

function Show-Dashboard {
    param($Current)

    Clear-Host
    $header = "llama.cpp prod Performance Monitor"
    $ts = Get-Date -Format "yyyy-MM-dd HH:mm:ss"
    Write-Host "  $header  |  Request #$requestCount  |  $ts" -ForegroundColor Cyan
    Write-Host ("  " + ("=" * 110)) -ForegroundColor Cyan

    Write-Host ""
    Write-Host "    CURRENT REQUEST                                           SESSION SUMMARY ($($history.Count) requests)"
    Write-Host "    ---------------                                           ------------------------------"

    $avgP = if ($history.Count -gt 0) { [math]::Round((($history | Measure-Object PromptTps -Average).Average),1) } else { 0 }
    $avgE = if ($history.Count -gt 0) { [math]::Round((($history | Measure-Object EvalTps -Average).Average),1) } else { 0 }
    $avgT = if ($history.Count -gt 0) { [math]::Round((($history | Measure-Object TotalTps -Average).Average),1) } else { 0 }
    $maxP = if ($history.Count -gt 0) { [math]::Round((($history | Measure-Object PromptTps -Maximum).Maximum),1) } else { 0 }
    $maxE = if ($history.Count -gt 0) { [math]::Round((($history | Measure-Object EvalTps -Maximum).Maximum),1) } else { 0 }

    $left1 = "    Prompt:  $([math]::Round($Current.PromptTps,1)) tok/s ($($Current.PromptTok) tokens)"
    $left2 = "    Output:  $([math]::Round($Current.EvalTps,1)) tok/s ($($Current.EvalTok) tokens)"
    $left3 = "    Total:   $([math]::Round($Current.TotalTps,1)) tok/s"

    # Live generation progress
    $liveStr = if ($Current.LiveTg -gt 0) { "$([math]::Round($Current.LiveTg,1)) t/s ($($Current.LiveTokens) decoded)" } else { "waiting..." }
    $left4 = "    Live tg: $liveStr"

    # Prompt processing progress
    $promptProgStr = if ($Current.PromptProgPct -gt 0) { "$([math]::Round($Current.PromptProgPct*100,0))% @ $([math]::Round($Current.PromptProgTps,0)) t/s" } else { "N/A" }
    $left5 = "    PP Eva:  $promptProgStr"

    $left6 = "    Draft:   $(if ($Current.DraftPct -gt 0) { "$([math]::Round($Current.DraftPct*100,1))%" } else { "N/A" })"
    $left7 = "    Graphs:  $(if ($Current.GraphsReuse -gt 0) { $Current.GraphsReuse } else { "N/A" })"

    $pad = 55

    Write-Host (Pad-Right $left1 $pad) "Avg prompt:  $avgP tok/s"
    Write-Host (Pad-Right $left2 $pad) "Avg output:  $avgE tok/s"
    Write-Host (Pad-Right $left3 $pad) "Avg total:   $avgT tok/s"
    Write-Host (Pad-Right $left4 $pad) "Peak prompt: $maxP tok/s"
    Write-Host (Pad-Right $left5 $pad) "Peak output: $maxE tok/s"
    Write-Host (Pad-Right $left6 $pad) ""
    Write-Host (Pad-Right $left7 $pad) ""

    Write-Host "`n    RECENT REQUESTS (last $($history.Count))"
    Write-Host "     #   Prompt   P-t/s   Eval    E-t/s   Total-t/s   Draft    Graphs   Context"
    Write-Host "     --  ------   ------  -----   ------  ---------   ------   ------   ---------"

    $i = 1
    foreach ($h in $history) {
        $draftStr = if ($h.DraftPct -gt 0) { "$([math]::Round($h.DraftPct*100,1))%" } else { "N/A" }
        $graphStr = if ($h.GraphsReuse -gt 0) { $h.GraphsReuse.ToString("N0") } else { "" }
        $ctx = if ($h.Context) { $h.Context.ToString("N0") } else { "" }
        $line = "     {0,-3}  {1,-6}  {2,6}  {3,-5}  {4,6}  {5,9}   {6,-6}   {7,-6}   {8}" -f
                $i, $h.PromptTok, [math]::Round($h.PromptTps,1), $h.EvalTok,
                [math]::Round($h.EvalTps,1), [math]::Round($h.TotalTps,1), $draftStr, $graphStr, $ctx
        Write-Host $line
        $i++
    }

    Write-Host "`n  Waiting for next request... (Ctrl+C to stop)" -ForegroundColor DarkGray
}

function Pad-Right {
    param([string]$Text, [int]$Width = 55)
    if ($Text.Length -ge $Width) { return $Text.Substring(0, $Width) }
    return $Text + (" " * ($Width - $Text.Length))
}

# ---------- main loop ----------
$running = $true
[Console]::TreatControlCAsInput = $true

while ($running) {
    try {
        if ([Console]::KeyAvailable) {
            $key = [Console]::ReadKey($true)
            if ($key.Key -eq "C" -and $key.Modifiers -eq "Control") { $running = $false; break }
        }

        # detect log rotation
        if (Test-Path $logDir) {
            $latest = Get-ChildItem -Path $logDir -Filter "*server_*.log" | Sort-Object LastWriteTime -Descending | Select-Object -First 1
            if ($latest -and $latest.FullName -ne $LogPath) {
                Write-Host "  Log rotated: $($latest.Name)" -ForegroundColor Yellow
                $LogPath = $latest.FullName
                $lastSize = 0
                $current = @{PromptTps=0; PromptTok=0; EvalTps=0; EvalTok=0; TotalTps=0; TotalTok=0; DraftPct=0; Context=0; GraphsReuse=0; HasPrompt=$false; HasEval=$false; LiveTg=0; LiveTokens=0; PromptProgPct=0; PromptProgTps=0}
            }
        }

        $fileInfo = Get-Item $LogPath -ErrorAction SilentlyContinue
        if (-not $fileInfo) { Start-Sleep -Milliseconds $RefreshMs; continue }

        $currentSize = $fileInfo.Length
        if ($currentSize -eq $lastSize) { Start-Sleep -Milliseconds $RefreshMs; continue }

        # read new content
        $stream = [System.IO.FileStream]::new($LogPath, 'Open', 'Read', 'ReadWrite')
        $stream.Seek($lastSize, 'Begin') | Out-Null
        $newContent = [System.IO.StreamReader]::new($stream).ReadToEnd()
        $stream.Close()
        $lastSize = $currentSize

        $hadProgress = $false

        foreach ($rawLine in ($newContent -split "`n")) {
            $rawLine = $rawLine.Trim()
