            # Strip [PID] + timestamp + facility + function: + id|task| prefix
            $payload = Get-CleanLine $rawLine
            if ($payload -eq "") { continue }

            # --- order matters: check prompt eval BEFORE eval time (elseif prevents double-match) ---
            # --- progress lines (real-time updates, don't use elseif — can coexist with final metrics) ---

            if ($payload -match $patternProgress) {
