                $current.TotalTps = if ($ms -gt 0) { $current.TotalTok / ($ms / 1000) } else { 0 }
            }
            elseif ($payload -match $patternDraft) {
                $current.DraftPct = [double]$Matches[1]
            }
            elseif ($payload -match $patternGraphs) {
                $current.GraphsReuse = [int]$Matches[1]
            }
            elseif ($payload -match $patternRelease) {
                $current.Context = [int]$Matches[1]

                if ($current.HasPrompt -and $current.HasEval) {
                    $requestCount++
                    $entry = [PSCustomObject]@{
                        PromptTok   = $current.PromptTok
                        PromptTps   = $current.PromptTps
                        EvalTok     = $current.EvalTok
                        EvalTps     = $current.EvalTps
                        TotalTps    = $current.TotalTps
                        DraftPct    = $current.DraftPct
                        Context     = $current.Context
                        GraphsReuse = $current.GraphsReuse
                    }
                    $history.Add($entry) | Out-Null
                    if ($history.Count -gt $maxHistory) { $history.RemoveAt(0) }

                    Show-Dashboard -Current $current
                    $hadProgress = $false

                    $current = @{
                        PromptTps=0; PromptTok=0; EvalTps=0; EvalTok=0
                        TotalTps=0; TotalTok=0; DraftPct=0; Context=0; GraphsReuse=0
                        HasPrompt=$false; HasEval=$false; LiveTg=0; LiveTokens=0
                        PromptProgPct=0; PromptProgTps=0
                    }
                }
            }
        }

        # refresh dashboard mid-request when progress lines arrive
