input.content:
# llama-cpp-log-monitor.ps1 - Dual GPU (multi-log) Performance Monitor
param(
    [int]$RefreshMs = 500
)

$logDir = "C:\llama.cpp-prod\logs"

# ---------- regex patterns ----------
$patternPrompt     = 'prompt eval time\s*=\s*([\d.]+)\s*ms\s*/\s*(\d+)\s*tokens?\s*\(\s*([\d.]+)\s*ms per token,\s*([\d.]+)\s*tokens per second\)'
$patternEval       = 'eval time\s*=\s*([\d.]+)\s*ms\s*/\s*(\d+)\s*tokens?\s*\(\s*([\d.]+)\s*ms per token,\s*([\d.]+)\s*tokens per second\)'
$patternTotal      = 'total time\s*=\s*([\d.]+)\s*ms\s*/\s*(\d+)\s*tokens?'
$patternDraft      = 'draft acceptance\s*=\s*([\d.]+)'
$patternRelease    = 'stop processing:\s*n_tokens\s*=\s*(\d+)'
$patternGraphs     = 'graphs reused\s*=\s*(\d+)'
$patternProgress   = 'n_decoded\s*=\s*(\d+),\s*tg\s*=\s*([\d.]+)\s*t/s'
$patternPromptProg = 'prompt processing,\s*n_tokens\s*=\s*(\d+),\s*progress\s*=\s*([\d.]+),\s*t\s*=\s*([\d.]+)\s*s\s*/\s*([\d.]+)\s*tokens per second'
$patternModelAlias = "spawning server instance with name=([^\s]+) on port"
$patternModelArgs  = "--alias\s+(\S+)"

# ---------- helper: strip [PID] + timestamp + facility + source function: + id|task| ----------
function Get-CleanLine {
    param([string]$Line)
    $clean = $Line -replace '^\[\d+\]\s*', ''
    $clean = $clean -replace '^[\d.]+\s+[A-Z]\s+\w+\s+[^:]+\:\s*(?:id\s+\d+\s*\|\s*task\s+-?\d+\s*\|\s*)?', ''
    return $clean
}

# ---------- per-log state ----------
# $watchers keys are log basename, each value is a hashtable with:
#   Path, LastSize, Current (metrics hashtable), History (ArrayList), RequestCount, Label, Alias
$watchers = @{}

function New-CurrentState {
    return @{
        PromptTps      = 0;  PromptTok      = 0
        EvalTps        = 0;  EvalTok        = 0
        TotalTps       = 0;  TotalTok       = 0
        DraftPct       = 0;  Context        = 0
        GraphsReuse    = 0
        HasPrompt      = $false; HasEval   = $false
        LiveTg         = 0;     LiveTokens = 0
        PromptProgPct  = 0;     PromptProgTps = 0
    }
}

function Get-OrCreateWatcher {
    param([string]$LogPath)
    $key = Split-Path $LogPath -Leaf
    if (-not $watchers.ContainsKey($key)) {
        # Try to extract GPU label from filename: B50 -> B50, B70 -> B70
        $label = $key
        if ($key -match '^(B\d+)') { $label = $Matches[1] }
        # Also try to find model alias from the log content
        $alias = ""
        if (Test-Path $LogPath) {
            $head = Get-Content $LogPath -TotalCount 500 -ErrorAction SilentlyContinue
            foreach ($line in $head) {
                if ($line -match $patternModelAlias) { $alias = $Matches[1]; break }
            }
        }
        $watchers[$key] = @{
            Path        = $LogPath
            LastSize    = (Get-Item $LogPath -ErrorAction SilentlyContinue | Select-Object -ExpandProperty Length)
            Current     = New-CurrentState
            History     = [System.Collections.ArrayList]::new()
            RequestCount = 0
            Label       = $label
            Alias       = if ($alias) { $alias } else { $label }
        }
        Write-Host "  Watching $label : $($watchers[$key].Alias)" -ForegroundColor Green
    }
    return $watchers[$key]
}

function Discover-Logs {
    if (-not (Test-Path $logDir)) { return @() }
    Get-ChildItem -Path $logDir -Filter "*server_*.log" | Sort-Object LastWriteTime -Descending | Select-Object -ExpandProperty FullName
}

# ---------- dashboard ----------
function Show-Dashboard {
    Clear-Host
    $ts = Get-Date -Format "yyyy-MM-dd HH:mm:ss"
    $header = "llama.cpp Dual GPU Performance Monitor"
    Write-Host "  $header  |  $ts" -ForegroundColor Cyan
    Write-Host ("  " + ("=" * 114)) -ForegroundColor Cyan
    Write-Host ""

    $keys = $watchers.Keys | Sort-Object
    if ($keys.Count -eq 0) {
        Write-Host "  No logs found. Waiting..." -ForegroundColor DarkGray
        return
    }

    # --- Per-GPU panels side by side ---
    $panelWidth = 55
    $panels = @()

    foreach ($key in $keys) {
        $w = $watchers[$key]
        $c = $w.Current
        $h = $w.History
        $label = $w.Label
        $alias = $w.Alias

        $avgP = if ($h.Count -gt 0) { [math]::Round((($h | Measure-Object PromptTps -Average).Average),1) } else { 0 }
        $avgE = if ($h.Count -gt 0) { [math]::Round((($h | Measure-Object EvalTps -Average).Average),1) } else { 0 }

        $lines = @()
        $lines += "    $label"
        $lines += "    " + ("-" * 48)
        $lines += "    Alias:    $alias"
        $lines += "    Requests: $($w.RequestCount)"
        $lines += ""
        $lines += "    Prompt:   $(if($c.HasPrompt){'$([math]::Round($c.PromptTps,1)) tok/s'}else{'---'})  ($($c.PromptTok) tok)"
        $lines += "    Output:   $(if($c.HasEval){'$([math]::Round($c.EvalTps,1)) tok/s'}else{'---'})  ($($c.EvalTok) tok)"
        $lines += "    Total:    $([math]::Round($c.TotalTps,1)) tok/s"

        $liveStr = if ($c.LiveTg -gt 0) { "$([math]::Round($c.LiveTg,1)) t/s ($($c.LiveTokens) decoded)" } else { "---" }
        $lines += "    Live tg:  $liveStr"

        $ppStr = if ($c.PromptProgPct -gt 0) { "$([math]::Round($c.PromptProgPct*100,0))% @ $([math]::Round($c.PromptProgTps,0)) t/s" } else { "---" }
        $lines += "    PP Eval:  $ppStr"

        $draftStr = if ($c.DraftPct -gt 0) { "$([math]::Round($c.DraftPct*100,1))%" } else { "---" }
        $lines += "    Draft:    $draftStr"
        $lines += "    Graphs:   $(if($c.GraphsReuse -gt 0){$c.GraphsReuse}else{'---'})"
        $lines += ""
        $lines += "    Session avg:"
        $lines += "      Prompt: $avgP t/s  |  Output: $avgE t/s"

        $panels += $lines
    }

    # Print panels side by side
    $maxLines = ($panels | ForEach-Object { $_.Count } | Measure-Object -Maximum).Maximum
    for ($i = 0; $i -lt $maxLines; $i++) {
        $row = "  "
        foreach ($panel in $panels) {
            $text = if ($i -lt $panel.Count) { $panel[$i] } else { "" }
            $row += Pad-Right -Text $text -Width $panelWidth
        }
        Write-Host $row
    }

    # --- Combined recent requests ---
    Write-Host ""
    Write-Host "    RECENT REQUESTS"
    Write-Host "     #   GPU  Prompt   P-t/s   Eval   E-t/s   Total-t/s   Draft    Graphs   Context"
    Write-Host "     --  ---  ------   ------  -----  ------  ---------   ------   ------   ---------"

    # Collect all history entries with GPU label, sort by recency (interleave)
    $combined = [System.Collections.ArrayList]::new()
    foreach ($key in $keys) {
        $w = $watchers[$key]
        $idx = 0
        foreach ($h in $w.History) {
            $idx++
            $combined.Add([PSCustomObject]@{
                GPU         = $w.Label
                PromptTok   = $h.PromptTok
                PromptTps   = $h.PromptTps
                EvalTok     = $h.EvalTok
                EvalTps     = $h.EvalTps
                TotalTps    = $h.TotalTps
                DraftPct    = $h.DraftPct
                GraphsReuse = $h.GraphsReuse
                Context     = $h.Context
                # Use negative index so newest entries sort last
                SortKey     = $idx
            }) | Out-Null
        }
