        elseif ($payload -match $patternRelease) {
            $curr.Context = [int]$Matches[1]
            if ($curr.HasPrompt -and $curr.HasEval) {
                $reqCount++
                $history.Add([PSCustomObject]@{
                    PromptTok=$curr.PromptTok; PromptTps=$curr.PromptTps
                    EvalTok=$curr.EvalTok; EvalTps=$curr.EvalTps
                    TotalTps=$curr.TotalTps; DraftPct=$curr.DraftPct
                    Context=$curr.Context; GraphsReuse=$curr.GraphsReuse
                }) | Out-Null
            }
            $curr = New-CurrentState
        }
    }

    Write-Host "Requests: $reqCount | n_decoded: $progCount | prompt-proc: $ppCount"
    if ($history.Count -gt 0) {
        $history | Format-Table PromptTok, PromptTps, EvalTok, EvalTps, TotalTps,
            @{N='Draft%';E={[math]::Round($_.DraftPct*100,1)}}, GraphsReuse, Context -AutoSize
    }
}

