file.content:
# llama-cpp-log-monitor.ps1 - Dual GPU (multi-log) Performance Monitor
param(
    [int]$RefreshMs = 500
)

$logDir = "C:\llama.cpp-prod\logs"

# ---------- regex patterns ----------
$patternPrompt     = 'prompt eval time\s*=\s*([\d.]+)\s*ms\s*/\s*(\d+)\s*tokens?\s*\(\s*([\d.]+)\s*ms per token,\s*([\d.]+)\s*tokens per second\)'
$patternEval       = 'eval time\s*=\s*([\d.]+)\s*ms\s*/\s*(\d+)\s*tokens?\s*\(\s*([\d.]+)\s*ms per token,\s*([\d.]+)\s*tokens per second\)'
$patternTotal      = 'total time\s*=\s*([\d.]+)\s*ms\s*/\s*(\d+)\s*tokens?'
$patternDraft      = 'draft acceptance\s*=\s*([\d.]+)'
$patternRelease    = 'stop processing:\s*n_tokens\s*=\s*(\d+)'
$patternGraphs     = 'graphs reused\s*=\s*(\d+)'
$patternProgress   = 'n_decoded\s*=\s*(\d+),\s*tg\s*=\s*([\d.]+)\s*t/s'
$patternPromptProg = 'prompt processing,\s*n_tokens\s*=\s*(\d+),\s*progress\s*=\s*([\d.]+),\s*t\s*=\s*([\d.]+)\s*s\s*/\s*([\d.]+)\s*tokens per second'
$patternModelAlias = "spawning server instance with name=([^\s]+) on port"
$patternModelArgs  = "--alias\s+(\S+)"

# ---------- helper: strip [PID] + timestamp + facility + source function: + id|task| ----------
function Get-CleanLine {
    param([string]$Line)
    $clean = $Line -replace '^\[\d+\]\s*', ''
    $clean = $clean -replace '^[\d.]+\s+[A-Z]\s+\w+\s+[^:]+\:\s*(?:id\s+\d+\s*\|\s*task\s+-?\d+\s*\|\s*)?', ''
    return $clean
}

# ---------- per-log state ----------
# $watchers keys are log basename, each value is a hashtable with:
#   Path, LastSize, Current (metrics hashtable), History (ArrayList), RequestCount, Label, Alias
$watchers = @{}

function New-CurrentState {
    return @{
        PromptTps      = 0;  PromptTok      = 0
        EvalTps        = 0;  EvalTok        = 0
        TotalTps       = 0;  TotalTok       = 0
        DraftPct       = 0;  Context        = 0
        GraphsReuse    = 0
        HasPrompt      = $false; HasEval   = $false
        LiveTg         = 0;     LiveTokens = 0
        PromptProgPct  = 0;     PromptProgTps = 0
    }
}

function Get-OrCreateWatcher {
    param([string]$LogPath)
    $key = Split-Path $LogPath -Leaf
    if (-not $watchers.ContainsKey($key)) {
        # Try to extract GPU label from filename: B50 -> B50, B70 -> B70
        $label = $key
        if ($key -match '^(B\d+)') { $label = $Matches[1] }
        # Also try to find model alias from the log content
        $alias = ""
        if (Test-Path $LogPath) {
            $head = Get-Content $LogPath -TotalCount 500 -ErrorAction SilentlyContinue
            foreach ($line in $head) {
                if ($line -match $patternModelAlias) { $alias = $Matches[1]; break }
            }
        }
        $watchers[$key] = @{
            Path        = $LogPath
            LastSize    = (Get-Item $LogPath -ErrorAction SilentlyContinue | Select-Object -ExpandProperty Length)
            Current     = New-CurrentState
            History     = [System.Collections.ArrayList]::new()
            RequestCount = 0
            Label       = $label
            Alias       = if ($alias) { $alias } else { $label }
        }
        Write-Host "  Watching $label : $($watchers[$key].Alias)" -ForegroundColor Green
    }
    return $watchers[$key]
}

function Discover-Logs {
    if (-not (Test-Path $logDir)) { return @() }
    $cutoff = (Get-Date).AddHours(-24)
    Get-ChildItem -Path $logDir -Filter "*server_*.log" |
        Where-Object { $_.LastWriteTime -gt $cutoff } |
        Sort-Object LastWriteTime -Descending |
        Select-Object -ExpandProperty FullName
}

# ---------- dashboard ----------
function Show-Dashboard {
    Clear-Host
    $ts = Get-Date -Format "yyyy-MM-dd HH:mm:ss"
    $header = "llama.cpp Dual GPU Performance Monitor"
    Write-Host "  $header  |  $ts" -ForegroundColor Cyan
    Write-Host ("  " + ("=" * 114)) -ForegroundColor Cyan
    Write-Host ""

    $keys = $watchers.Keys | Sort-Object
    if ($keys.Count -eq 0) {
        Write-Host "  No logs found. Waiting..." -ForegroundColor DarkGray
        return
    }

    # --- Per-GPU panels side by side ---
    $panelWidth = 55
    $panels = @()

    foreach ($key in $keys) {
        $w = $watchers[$key]
        $c = $w.Current
        $h = $w.History
        $label = $w.Label
        $alias = $w.Alias

        $avgP = if ($h.Count -gt 0) { [math]::Round((($h | Measure-Object PromptTps -Average).Average),1) } else { 0 }
        $avgE = if ($h.Count -gt 0) { [math]::Round((($h | Measure-Object EvalTps -Average).Average),1) } else { 0 }

        $lines = @()
        $lines += "    $label"
        $lines += "    " + ("-" * 48)
        $lines += "    Alias:    $alias"
        $lines += "    Requests: $($w.RequestCount)"
        $lines += ""
        $lines += "    Prompt:   $(if($c.HasPrompt){'$([math]::Round($c.PromptTps,1)) tok/s'}else{'---'})  ($($c.PromptTok) tok)"
        $lines += "    Output:   $(if($c.HasEval){'$([math]::Round($c.EvalTps,1)) tok/s'}else{'---'})  ($($c.EvalTok) tok)"
        $lines += "    Total:    $([math]::Round($c.TotalTps,1)) tok/s"

        $liveStr = if ($c.LiveTg -gt 0) { "$([math]::Round($c.LiveTg,1)) t/s ($($c.LiveTokens) decoded)" } else { "---" }
        $lines += "    Live tg:  $liveStr"

        $ppStr = if ($c.PromptProgPct -gt 0) { "$([math]::Round($c.PromptProgPct*100,0))% @ $([math]::Round($c.PromptProgTps,0)) t/s" } else { "---" }
        $lines += "    PP Eval:  $ppStr"

        $draftStr = if ($c.DraftPct -gt 0) { "$([math]::Round($c.DraftPct*100,1))%" } else { "---" }
        $lines += "    Draft:    $draftStr"
        $lines += "    Graphs:   $(if($c.GraphsReuse -gt 0){$c.GraphsReuse}else{'---'})"
        $lines += ""
        $lines += "    Session avg:"
        $lines += "      Prompt: $avgP t/s  |  Output: $avgE t/s"

        $panels += $lines
    }

    # Print panels side by side
    $maxLines = ($panels | ForEach-Object { $_.Count } | Measure-Object -Maximum).Maximum
    for ($i = 0; $i -lt $maxLines; $i++) {
        $row = "  "
        foreach ($panel in $panels) {
            $text = if ($i -lt $panel.Count) { $panel[$i] } else { "" }
            $row += Pad-Right -Text $text -Width $panelWidth
        }
        Write-Host $row
    }

    # --- Combined recent requests ---
    Write-Host ""
    Write-Host "    RECENT REQUESTS"
    Write-Host "     #   GPU  Prompt   P-t/s   Eval   E-t/s   Total-t/s   Draft    Graphs   Context"
    Write-Host "     --  ---  ------   ------  -----  ------  ---------   ------   ------   ---------"

    # Collect all history entries with GPU label, sort by recency (interleave)
    $combined = [System.Collections.ArrayList]::new()
    foreach ($key in $keys) {
        $w = $watchers[$key]
        $idx = 0
        foreach ($h in $w.History) {
            $idx++
            $combined.Add([PSCustomObject]@{
                GPU         = $w.Label
                PromptTok   = $h.PromptTok
                PromptTps   = $h.PromptTps
                EvalTok     = $h.EvalTok
                EvalTps     = $h.EvalTps
                TotalTps    = $h.TotalTps
                DraftPct    = $h.DraftPct
                GraphsReuse = $h.GraphsReuse
                Context     = $h.Context
                # Use negative index so newest entries sort last
                SortKey     = $idx
            }) | Out-Null
        }
    }

    # Show most recent 20 entries across all GPUs
    $display = $combined | Select-Object -Last 20
    $i = 1
    foreach ($r in $display) {
        $draftStr = if ($r.DraftPct -gt 0) { "$([math]::Round($r.DraftPct*100,1))%" } else { "N/A" }
        $graphStr = if ($r.GraphsReuse -gt 0) { $r.GraphsReuse.ToString("N0") } else { "" }
        $ctx      = if ($r.Context) { $r.Context.ToString("N0") } else { "" }
        $line = "     {0,-3}  {1,-3}  {2,-6}  {3,6}  {4,-5}  {5,6}  {6,9}   {7,-6}   {8,-6}   {9}" -f
                $i, $r.GPU, $r.PromptTok, [math]::Round($r.PromptTps,1), $r.EvalTok,
                [math]::Round($r.EvalTps,1), [math]::Round($r.TotalTps,1), $draftStr, $graphStr, $ctx
        Write-Host $line
        $i++
    }

    Write-Host "`n  Watching $($keys.Count) log(s)... (Ctrl+C to stop)" -ForegroundColor DarkGray
}

function Pad-Right {
    param([string]$Text, [int]$Width = 55)
    if ($Text.Length -ge $Width) { return $Text.Substring(0, $Width) }
    return $Text + (" " * ($Width - $Text.Length))
}

# ---------- process new content for one watcher ----------
function Process-WatcherLines {
    param($Watcher)

    $fileInfo = Get-Item $Watcher.Path -ErrorAction SilentlyContinue
    if (-not $fileInfo) { return $false }

    $currentSize = $fileInfo.Length
    if ($currentSize -eq $Watcher.LastSize) { return $false }
    if ($currentSize -lt $Watcher.LastSize) {
        # File was truncated (log rotation with same name)
        $Watcher.LastSize = 0
    }

    $stream = [System.IO.FileStream]::new($Watcher.Path, 'Open', 'Read', 'ReadWrite')
    $stream.Seek($Watcher.LastSize, 'Begin') | Out-Null
    $newContent = [System.IO.StreamReader]::new($stream).ReadToEnd()
    $stream.Close()
    $Watcher.LastSize = $currentSize

    $c = $Watcher.Current
    $hadProgress = $false

    foreach ($rawLine in ($newContent -split "`n")) {
        $rawLine = $rawLine.Trim()
        if ($rawLine -eq "") { continue }

        $payload = Get-CleanLine $rawLine
        if ($payload -eq "") { continue }

        # Check for model alias changes (model swap within the same log)
        if ($payload -match $patternModelAlias) {
            $Watcher.Alias = $Matches[1]
            continue
        }

        # Real-time progress lines (don't use elseif — can coexist with final metrics)
        if ($payload -match $patternProgress) {
            $c.LiveTokens = [int]$Matches[1]
            $c.LiveTg      = [double]$Matches[2]
            $hadProgress = $true
            continue
        }
        if ($payload -match $patternPromptProg) {
            $c.PromptProgPct = [double]$Matches[2]
            $c.PromptProgTps = [double]$Matches[4]
            $hadProgress = $true
            continue
        }

        # Final metrics (elseif chain — each line matches exactly one)
        if ($payload -match $patternPrompt) {
            $c.PromptTok = [int]$Matches[2]
            $c.PromptTps = [double]$Matches[4]
            $c.HasPrompt = $true
        }
        elseif ($payload -match $patternEval) {
            $c.EvalTok = [int]$Matches[2]
            $c.EvalTps = [double]$Matches[4]
            $c.HasEval = $true
        }
        elseif ($payload -match $patternTotal) {
            $c.TotalTok = [int]$Matches[2]
            $ms = [double]$Matches[1]
            $c.TotalTps = if ($ms -gt 0) { $c.TotalTok / ($ms / 1000) } else { 0 }
        }
        elseif ($payload -match $patternDraft) {
            $c.DraftPct = [double]$Matches[1]
        }
        elseif ($payload -match $patternGraphs) {
            $c.GraphsReuse = [int]$Matches[1]
        }
        elseif ($payload -match $patternRelease) {
            $c.Context = [int]$Matches[1]
            if ($c.HasPrompt -and $c.HasEval) {
                $Watcher.RequestCount++
                $entry = [PSCustomObject]@{
                    PromptTok   = $c.PromptTok
                    PromptTps   = $c.PromptTps
                    EvalTok     = $c.EvalTok
                    EvalTps     = $c.EvalTps
                    TotalTps    = $c.TotalTps
                    DraftPct    = $c.DraftPct
                    Context     = $c.Context
                    GraphsReuse = $c.GraphsReuse
                }
                $Watcher.History.Add($entry) | Out-Null
                if ($Watcher.History.Count -gt 20) { $Watcher.History.RemoveAt(0) }
            }
            $Watcher.Current = New-CurrentState
            $hadProgress = $false
        }
    }

    return $hadProgress
}

# ---------- startup ----------
Write-Host ""
Write-Host "llama.cpp Dual GPU Log Monitor" -ForegroundColor Cyan
Write-Host "Log dir: $logDir" -ForegroundColor Gray
Write-Host "Refresh: $RefreshMs ms" -ForegroundColor Gray
Write-Host ""

# Discover initial logs
$found = Discover-Logs
if ($found.Count -eq 0) {
    Write-Host "No *server_*.log files found in $logDir" -ForegroundColor Red
    Write-Host "Waiting for logs to appear..." -ForegroundColor DarkGray
}
foreach ($lp in $found) {
    Get-OrCreateWatcher -LogPath $lp | Out-Null
}

# ---------- main loop ----------
$running = $true
[Console]::TreatControlCAsInput = $true

while ($running) {
    try {
        if ([Console]::KeyAvailable) {
            $key = [Console]::ReadKey($true)
            if ($key.Key -eq "C" -and $key.Modifiers -eq "Control") { $running = $false; break }
        }

        # Discover new log files (model swaps, new instances)
        $currentLogs = Discover-Logs
        foreach ($lp in $currentLogs) {
            Get-OrCreateWatcher -LogPath $lp | Out-Null
        }

        # Remove watchers for files that no longer exist
        $staleKeys = @($watchers.Keys | Where-Object { -not (Test-Path $watchers[$_].Path) })
        foreach ($k in $staleKeys) { $watchers.Remove($k) }

        # Process each watcher
        $anyProgress = $false
        foreach ($key in @($watchers.Keys | Sort-Object)) {
            $w = $watchers[$key]
            if (Process-WatcherLines -Watcher $w) {
                $anyProgress = $true
            }
        }

        # Refresh dashboard
        Show-Dashboard

    }
    catch { Write-Host "Error: $_" -ForegroundColor Red }
    Start-Sleep -Milliseconds $RefreshMs
}

