# llama-cpp-log-monitor.ps1 - Dual GPU (multi-log) Performance Monitor
param(
    [int]$RefreshMs = 500
)

$logDir = "C:\llama.cpp-prod\logs"

# ---------- ANSI color codes (for flicker-free single-write rendering) ----------
$e = [char]27
$ansiCyan     = "$e[36m"
$ansiGreen    = "$e[32m"
$ansiYellow   = "$e[33m"
$ansiDarkGray = "$e[90m"
$ansiRed      = "$e[31m"
$ansiReset    = "$e[0m"
$ansiBold     = "$e[1m"

# ---------- regex patterns ----------
$patternPrompt     = 'prompt eval time\s*=\s*([\d.]+)\s*ms\s*/\s*(\d+)\s*tokens?\s*\(\s*([\d.]+)\s*ms per token,\s*([\d.]+)\s*tokens per second\)'
$patternEval       = 'eval time\s*=\s*([\d.]+)\s*ms\s*/\s*(\d+)\s*tokens?\s*\(\s*([\d.]+)\s*ms per token,\s*([\d.]+)\s*tokens per second\)'
$patternTotal      = 'total time\s*=\s*([\d.]+)\s*ms\s*/\s*(\d+)\s*tokens?'
$patternDraft      = 'draft acceptance\s*=\s*([\d.]+)'
$patternRelease    = 'stop processing:\s*n_tokens\s*=\s*(\d+)'
$patternGraphs     = 'graphs reused\s*=\s*(\d+)'
$patternProgress   = 'n_decoded\s*=\s*(\d+),\s*tg\s*=\s*([\d.]+)\s*t/s'
$patternPromptProg = 'prompt processing,\s*n_tokens\s*=\s*(\d+),\s*progress\s*=\s*([\d.]+),\s*t\s*=\s*([\d.]+)\s*s\s*/\s*([\d.]+)\s*tokens per second'
$patternModelAlias = "spawning server instance with name=([^\s]+) on port"

# ---------- helper: strip [PID] + timestamp + facility + source function: + id|task| ----------
function Get-CleanLine {
    param([string]$Line)
    $clean = $Line -replace '^\[\d+\]\s*', ''
    $clean = $clean -replace '^[\d.]+\s+[A-Z]\s+\w+\s+[^:]+\:\s*(?:id\s+\d+\s*\|\s*task\s+-?\d+\s*\|\s*)?', ''
    return $clean
}

# ---------- per-log state ----------
$watchers = @{}

function New-CurrentState {
    return @{
        PromptTps      = 0;  PromptTok      = 0
        EvalTps        = 0;  EvalTok        = 0
        TotalTps       = 0;  TotalTok       = 0
        DraftPct       = 0;  Context        = 0
        GraphsReuse    = 0
        HasPrompt      = $false; HasEval   = $false
        LiveTg         = 0;     LiveTokens = 0
        PromptProgPct  = 0;     PromptProgTps = 0
    }
}

function Get-OrCreateWatcher {
    param([string]$LogPath)
    $key = Split-Path $LogPath -Leaf
    if (-not $watchers.ContainsKey($key)) {
        $label = $key
        if ($key -match '^(B\d+)') { $label = $Matches[1] }
        $alias = ""
        if (Test-Path $LogPath) {
            $head = Get-Content $LogPath -TotalCount 500 -ErrorAction SilentlyContinue
            foreach ($line in $head) {
                if ($line -match $patternModelAlias) { $alias = $Matches[1]; break }
            }
        }
        $watchers[$key] = @{
            Path        = $LogPath
            LastSize    = (Get-Item $LogPath -ErrorAction SilentlyContinue | Select-Object -ExpandProperty Length)
            Current     = New-CurrentState
            History     = [System.Collections.ArrayList]::new()
            RequestCount = 0
            Label       = $label
            Alias       = if ($alias) { $alias } else { $label }
        }
    }
    return $watchers[$key]
}

function Discover-Logs {
    if (-not (Test-Path $logDir)) { return @() }
    $cutoff = (Get-Date).AddHours(-24)
    Get-ChildItem -Path $logDir -Filter "*server_*.log" |
        Where-Object { $_.LastWriteTime -gt $cutoff } |
        Sort-Object LastWriteTime -Descending |
        Select-Object -ExpandProperty FullName
}

# ---------- flicker-free dashboard ----------
function Show-Dashboard {
    $sb = [System.Text.StringBuilder]::new()
    $h = $Host.UI.RawUI.WindowSize.Height
    $w = $Host.UI.RawUI.WindowSize.Width
    $lineCount = 0

    # Helper: append a line to the buffer
    function A($text, $color) {
        if ($color) { $sb.Append($color) | Out-Null }
        $sb.Append($text) | Out-Null
        if ($color) { $sb.Append($ansiReset) | Out-Null }
        $sb.Append("`r`n") | Out-Null
        $script:lineCount++
    }

    $ts = Get-Date -Format "yyyy-MM-dd HH:mm:ss"
    A "  llama.cpp Dual GPU Performance Monitor  |  $ts" $ansiCyan
    A ("  " + ("=" * [math]::Min($w - 2, 114))) $ansiCyan
    A "" $null

    $keys = @($watchers.Keys | Sort-Object)
    if ($keys.Count -eq 0) {
        A "  No logs found in past 24h. Waiting..." $ansiDarkGray
        # pad remaining lines
        while ($lineCount -lt $h) { A (" " * [math]::Min($w - 1, 120)) $null }
        [Console]::SetCursorPosition(0, 0)
        [Console]::Write($sb.ToString())
        return
    }

    # --- Per-GPU panels side by side ---
    $panelWidth = 55
    $panels = @()

    foreach ($key in $keys) {
        $W = $watchers[$key]
        $c = $W.Current
        $hist = $W.History
        $label = $W.Label
        $alias = $W.Alias

        $avgP = if ($hist.Count -gt 0) { [math]::Round((($hist | Measure-Object PromptTps -Average).Average),1) } else { 0 }
        $avgE = if ($hist.Count -gt 0) { [math]::Round((($hist | Measure-Object EvalTps -Average).Average),1) } else { 0 }

        $lines = @(
            "    $label"
            "    " + ("-" * 48)
            "    Model:    $alias"
            "    Requests: $($W.RequestCount)"
            ""
            "    Prompt:   $(if($c.HasPrompt){"$([math]::Round($c.PromptTps,1)) tok/s"}else{'---'})  ($($c.PromptTok) tok)"
            "    Output:   $(if($c.HasEval){"$([math]::Round($c.EvalTps,1)) tok/s"}else{'---'})  ($($c.EvalTok) tok)"
            "    Total:    $([math]::Round($c.TotalTps,1)) tok/s"
            "    Live tg:  $(if($c.LiveTg -gt 0){"$([math]::Round($c.LiveTg,1)) t/s ($($c.LiveTokens) decoded)"}else{'---'})"
            "    PP Eval:  $(if($c.PromptProgPct -gt 0){"$([math]::Round($c.PromptProgPct*100,0))% @ $([math]::Round($c.PromptProgTps,0)) t/s"}else{'---'})"
            "    Draft:    $(if($c.DraftPct -gt 0){"$([math]::Round($c.DraftPct*100,1))%"}else{'---'})"
            "    Graphs:   $(if($c.GraphsReuse -gt 0){$c.GraphsReuse}else{'---'})"
            ""
            "    Session avg:"
            "      Prompt: $avgP t/s  |  Output: $avgE t/s"
        )
        $panels += ,$lines
    }

    # Print panels side by side
    $maxPanelLines = ($panels | ForEach-Object { $_.Count } | Measure-Object -Maximum).Maximum
    for ($i = 0; $i -lt $maxPanelLines; $i++) {
        $row = "  "
        foreach ($panel in $panels) {
            $text = if ($i -lt $panel.Count) { $panel[$i] } else { "" }
            $row += $text.PadRight($panelWidth)
        }
        A $row $null
    }

    # --- Combined recent requests ---
    A "" $null
    A "  RECENT REQUESTS" $ansiBold
    A ("  " + ("-" * 100)) $null
    A "  #   GPU  Prompt  P-t/s     Eval    E-t/s   Total-t/s   Draft    Graphs   Context" $null
    A "  --  ---  ------  ------   -----   ------  ---------   ------   ------   ---------" $null

    # Collect combined history
    $combined = [System.Collections.ArrayList]::new()
    foreach ($key in $keys) {
        $W = $watchers[$key]
        foreach ($h in $W.History) {
            $combined.Add([PSCustomObject]@{
                GPU         = $W.Label
                PromptTok   = $h.PromptTok
                PromptTps   = $h.PromptTps
                EvalTok     = $h.EvalTok
                EvalTps     = $h.EvalTps
                TotalTps    = $h.TotalTps
                DraftPct    = $h.DraftPct
                GraphsReuse = $h.GraphsReuse
                Context     = $h.Context
            }) | Out-Null
        }
    }

    $displayRows = [math]::Min($combined.Count, 15)  # limit display rows to keep dashboard compact
    $display = $combined | Select-Object -Last $displayRows
    $i = 1
    foreach ($r in $display) {
        $draftStr = if ($r.DraftPct -gt 0) { "$([math]::Round($r.DraftPct*100,1))%" } else { "N/A" }
        $graphStr = if ($r.GraphsReuse -gt 0) { $r.GraphsReuse.ToString("N0") } else { "" }
        $ctx      = if ($r.Context) { $r.Context.ToString("N0") } else { "" }
        $line = "  {0,-3}  {1,-3}  {2,-6}  {3,6}  {4,-6}  {5,6}  {6,9}   {7,-6}   {8,-6}   {9}" -f
                $i, $r.GPU, $r.PromptTok, [math]::Round($r.PromptTps,1), $r.EvalTok,
                [math]::Round($r.EvalTps,1), [math]::Round($r.TotalTps,1), $draftStr, $graphStr, $ctx
        A $line $null
        $i++
    }

    A "" $null
    A "  Watching $($keys.Count) log(s)... (Ctrl+C to stop)" $ansiDarkGray

    # Pad remaining lines to overwrite previous frame
    while ($lineCount -lt $h) {
        A (" " * [math]::Min($w - 1, 120)) $null
    }

