# ---------- dashboard builder (returns array of strings, no side effects) ----------
function Build-Dashboard {
    $lines = [System.Collections.ArrayList]::new()
    $ts = Get-Date -Format "yyyy-MM-dd HH:mm:ss"

    $lines.Add("  llama.cpp Dual GPU Performance Monitor  |  $ts") | Out-Null
    $lines.Add("  " + ("=" * 110)) | Out-Null
    $lines.Add("") | Out-Null

    $keys = @($watchers.Keys | Sort-Object)
    if ($keys.Count -eq 0) {
        $lines.Add("  No active logs found (past 24h). Waiting...") | Out-Null
        $lines.Add("  Looking in: $logDir") | Out-Null
        return $lines
    }

    # --- Per-GPU panels side by side (max 2) ---
    $panelWidth = 54
    $panelLines = @()

    foreach ($key in $keys) {
        $W = $watchers[$key]
        $c = $W.Current
        $hist = $W.History

        $avgP = if ($hist.Count -gt 0) { [math]::Round((($hist | Measure-Object PromptTps -Average).Average),1) } else { 0 }
        $avgE = if ($hist.Count -gt 0) { [math]::Round((($hist | Measure-Object EvalTps -Average).Average),1) } else { 0 }

        $p = [System.Collections.ArrayList]::new()
        $p.Add("    $($W.Label) ($($W.Alias))") | Out-Null
        $p.Add("    " + ("-" * 48)) | Out-Null
        $p.Add("    Requests: $($W.RequestCount)") | Out-Null
        $p.Add("") | Out-Null
        if ($c.HasPrompt) {
            $p.Add("    Prompt:   $([math]::Round($c.PromptTps,1)) tok/s  ($($c.PromptTok) tok)") | Out-Null
        } else {
            $p.Add("    Prompt:   ---") | Out-Null
        }
        if ($c.HasEval) {
            $p.Add("    Output:   $([math]::Round($c.EvalTps,1)) tok/s  ($($c.EvalTok) tok)") | Out-Null
        } else {
            $p.Add("    Output:   ---") | Out-Null
        }
        $p.Add("    Total:    $([math]::Round($c.TotalTps,1)) tok/s") | Out-Null
        if ($c.LiveTg -gt 0) {
            $p.Add("    Live tg:  $([math]::Round($c.LiveTg,1)) t/s  ($($c.LiveTokens) decoded)") | Out-Null
        } else {
            $p.Add("    Live tg:  ---") | Out-Null
        }
        if ($c.PromptProgPct -gt 0) {
            $p.Add("    PP Eval:  $([math]::Round($c.PromptProgPct*100,0))% @ $([math]::Round($c.PromptProgTps,0)) t/s") | Out-Null
        } else {
            $p.Add("    PP Eval:  ---") | Out-Null
        }
        if ($c.DraftPct -gt 0) {
            $p.Add("    Draft:    $([math]::Round($c.DraftPct*100,1))%") | Out-Null
        } else {
            $p.Add("    Draft:    ---") | Out-Null
        }
        if ($c.GraphsReuse -gt 0) {
            $p.Add("    Graphs:   $($c.GraphsReuse)") | Out-Null
        } else {
            $p.Add("    Graphs:   ---") | Out-Null
        }
        $p.Add("") | Out-Null
        $p.Add("    Session avg:") | Out-Null
        $p.Add("      Prompt: $avgP t/s  |  Output: $avgE t/s") | Out-Null

        $panelLines += ,$p
    }

    $maxP = 0
    foreach ($pl in $panelLines) { if ($pl.Count -gt $maxP) { $maxP = $pl.Count } }
    for ($i = 0; $i -lt $maxP; $i++) {
        $row = "  "
        foreach ($pl in $panelLines) {
            $text = if ($i -lt $pl.Count) { $pl[$i] } else { "" }
            $row += $text.PadRight($panelWidth)
        }
        $lines.Add($row) | Out-Null
    }

    # --- Combined recent requests ---
    $lines.Add("") | Out-Null
    $lines.Add("  RECENT REQUESTS") | Out-Null
    $lines.Add("  " + ("-" * 106)) | Out-Null
    $lines.Add("  #   GPU  Prompt    P-t/s   Eval     E-t/s   Total-t/s   Draft    Graphs   Context") | Out-Null
    $lines.Add("  --  ---  ------   ------   -----   ------  ---------   ------   ------   ---------") | Out-Null

    $combined = [System.Collections.ArrayList]::new()
    foreach ($key in $keys) {
        $W = $watchers[$key]
        foreach ($h in $W.History) {
            $combined.Add([PSCustomObject]@{
                GPU         = $W.Label
                PromptTok   = $h.PromptTok
                PromptTps   = $h.PromptTps
                EvalTok     = $h.EvalTok
                EvalTps     = $h.EvalTps
                TotalTps    = $h.TotalTps
                DraftPct    = $h.DraftPct
                GraphsReuse = $h.GraphsReuse
                Context     = $h.Context
            }) | Out-Null
        }
    }

    $display = $combined | Select-Object -Last 15
    $n = 1
    foreach ($r in $display) {
        $dStr = if ($r.DraftPct -gt 0) { "$([math]::Round($r.DraftPct*100,1))%" } else { "---" }
        $gStr = if ($r.GraphsReuse -gt 0) { $r.GraphsReuse.ToString("N0") } else { "" }
        $ctx  = if ($r.Context) { $r.Context.ToString("N0") } else { "" }
        $line = "  {0,-3}  {1,-3}  {2,-6}  {3,6}  {4,-6}  {5,6}  {6,9}   {7,-6}   {8,-6}   {9}" -f
                $n, $r.GPU, $r.PromptTok, [math]::Round($r.PromptTps,1), $r.EvalTok,
                [math]::Round($r.EvalTps,1), [math]::Round($r.TotalTps,1), $dStr, $gStr, $ctx
        $lines.Add($line) | Out-Null
        $n++
    }

    $lines.Add("") | Out-Null
    $lines.Add("  Watching $($keys.Count) log(s)  |  Ctrl+C to stop") | Out-Null

    return $lines
}

function Render-Dashboard {
    $lines = Build-Dashboard
    $h = $Host.UI.RawUI.WindowSize.Height
    $w = $Host.UI.RawUI.WindowSize.Width

    # Pad to full terminal height so old frames are fully overwritten
    while ($lines.Count -lt $h) {
        $lines.Add((" " * [math]::Min($w - 1, 120))) | Out-Null
    }
    # Trim if somehow we built more than fits
    while ($lines.Count -gt $h) {
        $lines.RemoveAt($lines.Count - 1)
    }

    [Console]::SetCursorPosition(0, 0)
    $out = $lines -join "`r`n"
    [Console]::Write($out)
}

# ---------- process new content for one watcher ----------
function Process-WatcherLines {
    param($Watcher)

    $fileInfo = Get-Item $Watcher.Path -ErrorAction SilentlyContinue
    if (-not $fileInfo) { return $false }

    $currentSize = $fileInfo.Length
    if ($currentSize -eq $Watcher.LastSize) { return $false }
    if ($currentSize -lt $Watcher.LastSize) {
        # Log rotated/truncated
        $Watcher.LastSize = 0
    }

    $stream = [System.IO.FileStream]::new($Watcher.Path, 'Open', 'Read', 'ReadWrite')
    $stream.Seek($Watcher.LastSize, 'Begin') | Out-Null
    $newContent = [System.IO.StreamReader]::new($stream).ReadToEnd()
    $stream.Close()
    $Watcher.LastSize = $currentSize

    $c = $Watcher.Current
    $hadProgress = $false

    foreach ($rawLine in ($newContent -split "`n")) {
        $rawLine = $rawLine.Trim()
        if ($rawLine -eq "") { continue }

        $payload = Get-CleanLine $rawLine
        if ($payload -eq "") { continue }

        if ($payload -match $patternModelAlias) {
            $Watcher.Alias = $Matches[1]
            continue
        }

        # Real-time progress lines
        if ($payload -match $patternProgress) {
            $c.LiveTokens = [int]$Matches[1]
            $c.LiveTg      = [double]$Matches[2]
            $hadProgress = $true
            continue
        }
        if ($payload -match $patternPromptProg) {
            $c.PromptProgPct = [double]$Matches[2]
            $c.PromptProgTps = [double]$Matches[4]
            $hadProgress = $true
            continue
        }

        # Final metrics (elseif chain — each line matches exactly one)
        if ($payload -match $patternPrompt) {
            $c.PromptTok = [int]$Matches[2]
            $c.PromptTps = [double]$Matches[4]
            $c.HasPrompt = $true
        }
        elseif ($payload -match $patternEval) {
            $c.EvalTok = [int]$Matches[2]
            $c.EvalTps = [double]$Matches[4]
            $c.HasEval = $true
        }
        elseif ($payload -match $patternTotal) {
            $c.TotalTok = [int]$Matches[2]
            $ms = [double]$Matches[1]
            $c.TotalTps = if ($ms -gt 0) { $c.TotalTok / ($ms / 1000) } else { 0 }
        }
        elseif ($payload -match $patternDraft) {
            $c.DraftPct = [double]$Matches[1]
        }
        elseif ($payload -match $patternGraphs) {
            $c.GraphsReuse = [int]$Matches[1]
        }
        elseif ($payload -match $patternRelease) {
            $c.Context = [int]$Matches[1]
            if ($c.HasPrompt -and $c.HasEval) {
                $Watcher.RequestCount++
                $entry = [PSCustomObject]@{
                    PromptTok   = $c.PromptTok
                    PromptTps   = $c.PromptTps
                    EvalTok     = $c.EvalTok
                    EvalTps     = $c.EvalTps
                    TotalTps    = $c.TotalTps
                    DraftPct    = $c.DraftPct
                    Context     = $c.Context
                    GraphsReuse = $c.GraphsReuse
                }
                $Watcher.History.Add($entry) | Out-Null
                if ($Watcher.History.Count -gt 30) { $Watcher.History.RemoveAt(0) }
            }
            $Watcher.Current = New-CurrentState
            $hadProgress = $false
        }
    }

    return $hadProgress
}

