input.content:
# llama-cpp-log-monitor.ps1 - Dual GPU (multi-log) Performance Monitor
param(
    [int]$RefreshMs = 500
)

$logDir = "C:\llama.cpp-prod\logs"

# ---------- regex patterns ----------
$patternPrompt     = 'prompt eval time\s*=\s*([\d.]+)\s*ms\s*/\s*(\d+)\s*tokens?\s*\(\s*([\d.]+)\s*ms per token,\s*([\d.]+)\s*tokens per second\)'
$patternEval       = 'eval time\s*=\s*([\d.]+)\s*ms\s*/\s*(\d+)\s*tokens?\s*\(\s*([\d.]+)\s*ms per token,\s*([\d.]+)\s*tokens per second\)'
$patternTotal      = 'total time\s*=\s*([\d.]+)\s*ms\s*/\s*(\d+)\s*tokens?'
$patternDraft      = 'draft acceptance\s*=\s*([\d.]+)'
$patternRelease    = 'stop processing:\s*n_tokens\s*=\s*(\d+)'
$patternGraphs     = 'graphs reused\s*=\s*(\d+)'
$patternProgress   = 'n_decoded\s*=\s*(\d+),\s*tg\s*=\s*([\d.]+)\s*t/s'
$patternPromptProg = 'prompt processing,\s*n_tokens\s*=\s*(\d+),\s*progress\s*=\s*([\d.]+),\s*t\s*=\s*([\d.]+)\s*s\s*/\s*([\d.]+)\s*tokens per second'
$patternModelAlias = "spawning server instance with name=([^\s]+) on port"

function Get-CleanLine {
    param([string]$Line)
    $clean = $Line -replace '^\[\d+\]\s*', ''
    $clean = $clean -replace '^[\d.]+\s+[A-Z]\s+\w+\s+[^:]+\:\s*(?:id\s+\d+\s*\|\s*task\s+-?\d+\s*\|\s*)?', ''
    return $clean
}

# ---------- per-log state ----------
$watchers = @{}

function New-CurrentState {
    return @{
        PromptTps=0; PromptTok=0; EvalTps=0; EvalTok=0; TotalTps=0; TotalTok=0
        DraftPct=0; Context=0; GraphsReuse=0; HasPrompt=$false; HasEval=$false
        LiveTg=0; LiveTokens=0; PromptProgPct=0; PromptProgTps=0
    }
}

function Seed-Watcher {
    param($Watcher)
    # One-time parse of entire file to populate history
    if (-not (Test-Path $Watcher.Path)) { return }
    $content = Get-Content $Watcher.Path -ReadCount 0 -ErrorAction SilentlyContinue
    if (-not $content) { return }

    $c = New-CurrentState
    foreach ($rawLine in $content) {
        $rawLine = $rawLine.Trim()
        if ($rawLine -eq "") { continue }
        $payload = Get-CleanLine $rawLine
        if ($payload -eq "") { continue }

        if ($payload -match $patternModelAlias) {
            $Watcher.Alias = $Matches[1]
            continue
        }
        if ($payload -match $patternProgress -or $payload -match $patternPromptProg) { continue }

        if ($payload -match $patternPrompt) {
            $c.PromptTok = [int]$Matches[2]; $c.PromptTps = [double]$Matches[4]; $c.HasPrompt = $true
        }
        elseif ($payload -match $patternEval) {
            $c.EvalTok = [int]$Matches[2]; $c.EvalTps = [double]$Matches[4]; $c.HasEval = $true
        }
        elseif ($payload -match $patternTotal) {
            $c.TotalTok = [int]$Matches[2]
            $ms = [double]$Matches[1]
            $c.TotalTps = if ($ms -gt 0) { $c.TotalTok / ($ms / 1000) } else { 0 }
        }
        elseif ($payload -match $patternDraft) { $c.DraftPct = [double]$Matches[1] }
        elseif ($payload -match $patternGraphs) { $c.GraphsReuse = [int]$Matches[1] }
        elseif ($payload -match $patternRelease) {
            $c.Context = [int]$Matches[1]
            if ($c.HasPrompt -and $c.HasEval) {
                $Watcher.RequestCount++
                $Watcher.History.Add([PSCustomObject]@{
                    PromptTok=$c.PromptTok; PromptTps=$c.PromptTps; EvalTok=$c.EvalTok
                    EvalTps=$c.EvalTps; TotalTps=$c.TotalTps; DraftPct=$c.DraftPct
                    Context=$c.Context; GraphsReuse=$c.GraphsReuse
                }) | Out-Null
            }
            $c = New-CurrentState
        }
    }
    # Set file pointer to end so tail mode starts from here
    $Watcher.LastSize = (Get-Item $Watcher.Path -ErrorAction SilentlyContinue | Select-Object -ExpandProperty Length)
}

# ---------- dashboard ----------
function Show-Dashboard {
    Clear-Host

    $ts = Get-Date -Format "yyyy-MM-dd HH:mm:ss"
    Write-Host "  llama.cpp Dual GPU Performance Monitor  |  $ts" -ForegroundColor Cyan
    Write-Host ("  " + ("=" * 110))

    $keys = @($watchers.Keys | Sort-Object)
    if ($keys.Count -eq 0) {
        Write-Host "`n  No active logs found (past 24h)." -ForegroundColor DarkGray
        Write-Host "  Looking in: $logDir" -ForegroundColor DarkGray
        Write-Host "`n  Waiting... (Ctrl+C to stop)" -ForegroundColor DarkGray
        return
    }

    # --- GPU panels side by side ---
    Write-Host ""
    $panelW = 54
    $maxLines = 0
    $allPanels = @()

    foreach ($key in $keys) {
        $W = $watchers[$key]
        $c = $W.Current
        $h = $W.History
        $avgP = if ($h.Count -gt 0) { [math]::Round((($h | Measure-Object PromptTps -Average).Average),1) } else { 0 }
        $avgE = if ($h.Count -gt 0) { [math]::Round((($h | Measure-Object EvalTps -Average).Average),1) } else { 0 }

        $lines = [System.Collections.ArrayList]::new()
        [void]$lines.Add("  $($W.Label)  [$($W.Alias)]")
        [void]$lines.Add("  " + ("-" * 48))
        [void]$lines.Add("  Requests: $($W.RequestCount)")
        [void]$lines.Add("")
        [void]$lines.Add("  Prompt:   $(if($c.HasPrompt){'{0,7} tok/s' -f [math]::Round($c.PromptTps,1)}else{'    ---'})   ($($c.PromptTok) tok)")
        [void]$lines.Add("  Output:   $(if($c.HasEval){'{0,7} tok/s' -f [math]::Round($c.EvalTps,1)}else{'    ---'})   ($($c.EvalTok) tok)")
        [void]$lines.Add("  Total:    {0,7} tok/s" -f [math]::Round($c.TotalTps,1))
        [void]$lines.Add("  Live tg:  $(if($c.LiveTg -gt 0){'{0,7} t/s' -f [math]::Round($c.LiveTg,1) + '   (' + $c.LiveTokens + ' tok)'}else{'    ---'})")
        [void]$lines.Add("  PP Eval:  $(if($c.PromptProgPct -gt 0){'{0,7}%' -f [math]::Round($c.PromptProgPct*100,0) + ' @ ' + [math]::Round($c.PromptProgTps,0) + ' t/s'}else{'    ---'})")
        [void]$lines.Add("  Draft:    $(if($c.DraftPct -gt 0){'{0,7}%' -f [math]::Round($c.DraftPct*100,1)}else{'    ---'})")
        [void]$lines.Add("  Graphs:   $(if($c.GraphsReuse -gt 0){$c.GraphsReuse}else{'---'})")
        [void]$lines.Add("")
        [void]$lines.Add("  Session avg:")
        [void]$lines.Add("    Prompt: $avgP t/s  |  Output: $avgE t/s")

        $allPanels += ,$lines
        if ($lines.Count -gt $maxLines) { $maxLines = $lines.Count }
    }

    for ($i = 0; $i -lt $maxLines; $i++) {
        $out = ""
        foreach ($panel in $allPanels) {
            $txt = if ($i -lt $panel.Count) { $panel[$i] } else { "" }
            $out += $txt.PadRight($panelW)
        }
        Write-Host $out
    }

    # --- Combined recent requests ---
    Write-Host ""
    Write-Host "  RECENT REQUESTS"
    Write-Host ("  " + ("-" * 106))
    Write-Host "  #   GPU  Prompt    P-t/s   Eval     E-t/s   Total-t/s   Draft    Graphs   Context"

    $combined = [System.Collections.ArrayList]::new()
    foreach ($key in $keys) {
        $W = $watchers[$key]
        foreach ($h in $W.History) {
            [void]$combined.Add([PSCustomObject]@{GPU=$W.Label; PromptTok=$h.PromptTok; PromptTps=$h.PromptTps; EvalTok=$h.EvalTok; EvalTps=$h.EvalTps; TotalTps=$h.TotalTps; DraftPct=$h.DraftPct; GraphsReuse=$h.GraphsReuse; Context=$h.Context})
        }
    }

    $n = 1
    foreach ($r in ($combined | Select-Object -Last 15)) {
        $dS = if ($r.DraftPct -gt 0) { "{0,6}%" -f [math]::Round($r.DraftPct*100,1) } else { "   ---" }
        $gS = if ($r.GraphsReuse -gt 0) { "{0,6}" -f $r.GraphsReuse } else { "      " }
        $ctx = if ($r.Context) { $r.Context.ToString("N0") } else { "" }
        $line = "  {0,-3}  {1,-3}  {2,-6}  {3,6}  {4,-6}  {5,6}  {6,9}   {7}   {8}   {9}" -f
                $n, $r.GPU, $r.PromptTok, [math]::Round($r.PromptTps,1), $r.EvalTok,
                [math]::Round($r.EvalTps,1), [math]::Round($r.TotalTps,1), $dS, $gS, $ctx
        Write-Host $line
        $n++
    }

    Write-Host "`n  Watching $($keys.Count) log(s)... (Ctrl+C to stop)" -ForegroundColor DarkGray
}

# ---------- tail (new content only) ----------
function Process-WatcherTail {
    param($Watcher)

    $fileInfo = Get-Item $Watcher.Path -ErrorAction SilentlyContinue
    if (-not $fileInfo) { return $false }

    $sz = $fileInfo.Length
    if ($sz -eq $Watcher.LastSize) { return $false }
    if ($sz -lt $Watcher.LastSize) { $Watcher.LastSize = 0 }

    $stream = [System.IO.FileStream]::new($Watcher.Path, 'Open', 'Read', 'ReadWrite')
    $stream.Seek($Watcher.LastSize, 'Begin') | Out-Null
    $newContent = [System.IO.StreamReader]::new($stream).ReadToEnd()
    $stream.Close()
    $Watcher.LastSize = $sz

    $c = $Watcher.Current
    $hadProgress = $false

    foreach ($rawLine in ($newContent -split "`n")) {
        $rawLine = $rawLine.Trim()
        if ($rawLine -eq "") { continue }
        $payload = Get-CleanLine $rawLine
        if ($payload -eq "") { continue }

        if ($payload -match $patternModelAlias) { $Watcher.Alias = $Matches[1]; continue }

        if ($payload -match $patternProgress) {
            $c.LiveTokens = [int]$Matches[1]; $c.LiveTg = [double]$Matches[2]
            $hadProgress = $true; continue
        }
        if ($payload -match $patternPromptProg) {
            $c.PromptProgPct = [double]$Matches[2]; $c.PromptProgTps = [double]$Matches[4]
            $hadProgress = $true; continue
        }

        if ($payload -match $patternPrompt) {
            $c.PromptTok = [int]$Matches[2]; $c.PromptTps = [double]$Matches[4]; $c.HasPrompt = $true
        }
        elseif ($payload -match $patternEval) {
            $c.EvalTok = [int]$Matches[2]; $c.EvalTps = [double]$Matches[4]; $c.HasEval = $true
        }
        elseif ($payload -match $patternTotal) {
            $c.TotalTok = [int]$Matches[2]
            $ms = [double]$Matches[1]
            $c.TotalTps = if ($ms -gt 0) { $c.TotalTok / ($ms / 1000) } else { 0 }
        }
        elseif ($payload -match $patternDraft) { $c.DraftPct = [double]$Matches[1] }
        elseif ($payload -match $patternGraphs) { $c.GraphsReuse = [int]$Matches[1] }
        elseif ($payload -match $patternRelease) {
            $c.Context = [int]$Matches[1]
            if ($c.HasPrompt -and $c.HasEval) {
                $Watcher.RequestCount++
                [void]$Watcher.History.Add([PSCustomObject]@{PromptTok=$c.PromptTok; PromptTps=$c.PromptTps; EvalTok=$c.EvalTok; EvalTps=$c.EvalTps; TotalTps=$c.TotalTps; DraftPct=$c.DraftPct; Context=$c.Context; GraphsReuse=$c.GraphsReuse})
                if ($Watcher.History.Count -gt 30) { $Watcher.History.RemoveAt(0) }
            }
            $Watcher.Current = New-CurrentState
            $hadProgress = $false
        }
    }
    return $hadProgress
}

# ---------- discovery ----------
function Discover-Logs {
    if (-not (Test-Path $logDir)) { return @() }
    $cutoff = (Get-Date).AddHours(-24)
    Get-ChildItem -Path $logDir -Filter "*server_*.log" |
        Where-Object { $_.LastWriteTime -gt $cutoff } |
        Sort-Object LastWriteTime -Descending |
        Select-Object -ExpandProperty FullName
}

# ---------- startup ----------
Clear-Host
Write-Host "llama.cpp Dual GPU Log Monitor" -ForegroundColor Cyan
Write-Host "Log dir: $logDir" -ForegroundColor Gray
Write-Host ""

$found = Discover-Logs
if ($found.Count -eq 0) {
    Write-Host "No *server_*.log files found (past 24h). Waiting..." -ForegroundColor Red
}

foreach ($lp in $found) {
    $key = Split-Path $lp -Leaf
    $label = $key; if ($key -match '^(B\d+)') { $label = $Matches[1] }
    $alias = ""
    $head = Get-Content $lp -TotalCount 500 -ErrorAction SilentlyContinue
    foreach ($line in $head) {
        if ($line -match $patternModelAlias) { $alias = $Matches[1]; break }
    }

    $w = @{
        Path=$lp; LastSize=0; Current=New-CurrentState; RequestCount=0
        History=[System.Collections.ArrayList]::new(); Label=$label
        Alias=if($alias){$alias}else{$label}
    }
    Write-Host "  Seeding $label : $($w.Alias)..." -ForegroundColor Green
    Seed-Watcher -Watcher $w
    $watchers[$key] = $w
    Write-Host "    -> $($w.RequestCount) requests, $($w.History.Count) in history" -ForegroundColor DarkGray
}

Write-Host ""
Write-Host "Starting monitor... (Ctrl+C to stop)" -ForegroundColor DarkGray
Start-Sleep -Milliseconds 500

# ---------- main loop ----------
$running = $true

# Proper Ctrl+C handling
try {
    [Console]::TreatControlCAsInput = $false
    $null = Register-EngineEvent -SourceIdentifier PowerShell.Exiting -Action {}
}
catch { }

while ($running) {
    try {
        # Check for Ctrl+C via key poll (quick, doesn't block)
        if ([Console]::KeyAvailable) {
            $key = [Console]::ReadKey($true)
            if (($key.Key -eq "C" -and $key.Modifiers -eq "Control") -or $key.Key -eq "Escape") {
                $running = $false
                break
            }
        }

        # Discover new logs
        $currentLogs = Discover-Logs
        foreach ($lp in $currentLogs) {
            $k = Split-Path $lp -Leaf
            if (-not $watchers.ContainsKey($k)) {
                $label = $k; if ($k -match '^(B\d+)') { $label = $Matches[1] }
                $alias = ""
                $head = Get-Content $lp -TotalCount 200 -ErrorAction SilentlyContinue
                foreach ($line in $head) {
                    if ($line -match $patternModelAlias) { $alias = $Matches[1]; break }
                }
                $watchers[$k] = @{
                    Path=$lp; LastSize=0; Current=New-CurrentState; RequestCount=0
                    History=[System.Collections.ArrayList]::new(); Label=$label
                    Alias=if($alias){$alias}else{$label}
                }
                # Seed immediately so dashboard shows data
                Seed-Watcher -Watcher $watchers[$k]
            }
        }

        # Remove stale watchers
        $stale = @($watchers.Keys | Where-Object { -not (Test-Path $watchers[$_].Path) })
        foreach ($k in $stale) { $watchers.Remove($k) }

        # Process new content from each log
        foreach ($key in @($watchers.Keys | Sort-Object)) {
            Process-WatcherTail -Watcher $watchers[$key] | Out-Null
        }

        Show-Dashboard
    }
    catch {
        # Show error at bottom, continue
        Write-Host "`n  Error: $($_.Exception.Message.Substring(0, [math]::Min(80, $_.Exception.Message.Length)))" -ForegroundColor Red
    }
    Start-Sleep -Milliseconds $RefreshMs
}

# ---------- cleanup ----------
Clear-Host
Write-Host ""
Write-Host "Session Summary" -ForegroundColor Cyan
Write-Host "========================================"
foreach ($key in @($watchers.Keys | Sort-Object)) {
    Write-Host "  $($watchers[$key].Label): $($watchers[$key].RequestCount) requests ($($watchers[$key].Alias))" -ForegroundColor Yellow
}
