                [void]$h.Add([PSCustomObject]@{PromptTok=$c.PromptTok; PromptTps=[math]::Round($c.PromptTps,1); EvalTok=$c.EvalTok; EvalTps=[math]::Round($c.EvalTps,1); TotalTps=[math]::Round($c.TotalTps,1); DraftPct=[math]::Round($c.DraftPct*100,1); GraphsReuse=$c.GraphsReuse; Context=$c.Context})
            }
            $c = @{PromptTps=0; PromptTok=0; EvalTps=0; EvalTok=0; TotalTps=0; TotalTok=0; DraftPct=0; Context=0; GraphsReuse=0; HasPrompt=$false; HasEval=$false}
        }
    }
    Write-Host "Requests: $rc"
    $h | Format-Table PromptTok, PromptTps, EvalTok, EvalTps, TotalTps, DraftPct, GraphsReuse, Context -AutoSize
    Write-Host ""
}
Write-Host "PASS" -ForegroundColor Green

