311	                $head = Get-Content $lp -TotalCount 200 -ErrorAction SilentlyContinue
312	                foreach ($line in $head) {
313	                    if ($line -match $patternModelAlias) { $alias = $Matches[1]; break }
314	                }
315	                $watchers[$k] = @{
316	                    Path=$lp; LastSize=0; Current=New-CurrentState; RequestCount=0
317	                    History=[System.Collections.ArrayList]::new(); Label=$label
318	                    Alias=if($alias){$alias}else{$label}
319	                }
320	                # Seed immediately so dashboard shows data
321	                Seed-Watcher -Watcher $watchers[$k]
322	            }
323	        }
324	
325	        # Remove stale watchers
326	        $stale = @($watchers.Keys | Where-Object { -not (Test-Path $watchers[$_].Path) })
327	        foreach ($k in $stale) { $watchers.Remove($k) }
328	
329	        # Process new content from each log
330	        foreach ($key in @($watchers.Keys | Sort-Object)) {
