334	        Show-Dashboard
335	    }
336	    catch {
337	        # Show error at bottom, continue
338	        Write-Host "`n  Error: $($_.Exception.Message.Substring(0, [math]::Min(80, $_.Exception.Message.Length)))" -ForegroundColor Red
339	    }
340	    Start-Sleep -Milliseconds $RefreshMs
341	}
342	
343	# ---------- cleanup ----------
344	Clear-Host
345	Write-Host ""
346	Write-Host "Session Summary" -ForegroundColor Cyan
347	Write-Host "========================================"
348	foreach ($key in @($watchers.Keys | Sort-Object)) {
349	    Write-Host "  $($watchers[$key].Label): $($watchers[$key].RequestCount) requests ($($watchers[$key].Alias))" -ForegroundColor Yellow
350	}
351	Write-Host ""
