        [void]$lines.Add("  Prompt:   $(if($c.HasPrompt){'{0,7} tok/s' -f [math]::Round($c.PromptTps,1)}else{'    ---'})   ($($c.PromptTok) tok)")
        [void]$lines.Add("  Output:   $(if($c.HasEval){'{0,7} tok/s' -f [math]::Round($c.EvalTps,1)}else{'    ---'})   ($($c.EvalTok) tok)")
        [void]$lines.Add("  Total:    {0,7} tok/s" -f [math]::Round($c.TotalTps,1))
        [void]$lines.Add("  Live tg:  $(if($c.LiveTg -gt 0){'{0,7} t/s' -f [math]::Round($c.LiveTg,1) + '   (' + $c.LiveTokens + ' tok)'}else{'    ---'})")
        [void]$lines.Add("  PP Eval:  $(if($c.PromptProgPct -gt 0){'{0,7}%' -f [math]::Round($c.PromptProgPct*100,0) + ' @ ' + [math]::Round($c.PromptProgTps,0) + ' t/s'}else{'    ---'})")
        [void]$lines.Add("  Draft:    $(if($c.DraftPct -gt 0){'{0,7}%' -f [math]::Round($c.DraftPct*100,1)}else{'    ---'})")
        [void]$lines.Add("  Graphs:   $(if($c.GraphsReuse -gt 0){$c.GraphsReuse}else{'---'})")
        [void]$lines.Add("")
        [void]$lines.Add("  Session avg:")
        [void]$lines.Add("    Prompt: $avgP t/s  |  Output: $avgE t/s")

        $allPanels += ,$lines
        if ($lines.Count -gt $maxLines) { $maxLines = $lines.Count }
    }

    for ($i = 0; $i -lt $maxLines; $i++) {
        $out = ""
        foreach ($panel in $allPanels) {
            $txt = if ($i -lt $panel.Count) { $panel[$i] } else { "" }
            $out += $txt.PadRight($panelW)
        }
        Write-Host $out
    }

    # --- Combined recent requests ---
    Write-Host ""
    Write-Host "  RECENT REQUESTS"
    Write-Host ("  " + ("-" * 106))
    Write-Host "  #   GPU  Prompt    P-t/s   Eval     E-t/s   Total-t/s   Draft    Graphs   Context"

    $combined = [System.Collections.ArrayList]::new()
    foreach ($key in $keys) {
