# ---------- tail (new content only) ----------
function Process-WatcherTail {
    param($Watcher)

    $fileInfo = Get-Item $Watcher.Path -ErrorAction SilentlyContinue
    if (-not $fileInfo) { return $false }

    $sz = $fileInfo.Length
    if ($sz -eq $Watcher.LastSize) { return $false }
    if ($sz -lt $Watcher.LastSize) { $Watcher.LastSize = 0 }

    $stream = [System.IO.FileStream]::new($Watcher.Path, 'Open', 'Read', 'ReadWrite')
    $stream.Seek($Watcher.LastSize, 'Begin') | Out-Null
    $newContent = [System.IO.StreamReader]::new($stream).ReadToEnd()
    $stream.Close()
    $Watcher.LastSize = $sz

    $c = $Watcher.Current
    $hadProgress = $false

    foreach ($rawLine in ($newContent -split "`n")) {
        $rawLine = $rawLine.Trim()
        if ($rawLine -eq "") { continue }
        $payload = Get-CleanLine $rawLine
        if ($payload -eq "") { continue }

        if ($payload -match $patternModelAlias) { $Watcher.Alias = $Matches[1]; continue }

        if ($payload -match $patternProgress) {
            $c.LiveTokens = [int]$Matches[1]; $c.LiveTg = [double]$Matches[2]
            $hadProgress = $true; continue
        }
        if ($payload -match $patternPromptProg) {
            $c.PromptProgPct = [double]$Matches[2]; $c.PromptProgTps = [double]$Matches[4]
            $hadProgress = $true; continue
        }

        if ($payload -match $patternPrompt) {
            $c.PromptTok = [int]$Matches[2]; $c.PromptTps = [double]$Matches[4]; $c.HasPrompt = $true
        }
        elseif ($payload -match $patternEval) {
            $c.EvalTok = [int]$Matches[2]; $c.EvalTps = [double]$Matches[4]; $c.HasEval = $true
        }
        elseif ($payload -match $patternTotal) {
            $c.TotalTok = [int]$Matches[2]
            $ms = [double]$Matches[1]
            $c.TotalTps = if ($ms -gt 0) { $c.TotalTok / ($ms / 1000) } else { 0 }
        }
        elseif ($payload -match $patternDraft) { $c.DraftPct = [double]$Matches[1] }
        elseif ($payload -match $patternGraphs) { $c.GraphsReuse = [int]$Matches[1] }
        elseif ($payload -match $patternRelease) {
            $c.Context = [int]$Matches[1]
            if ($c.HasPrompt -and $c.HasEval) {
                $Watcher.RequestCount++
                [void]$Watcher.History.Add([PSCustomObject]@{PromptTok=$c.PromptTok; PromptTps=$c.PromptTps; EvalTok=$c.EvalTok; EvalTps=$c.EvalTps; TotalTps=$c.TotalTps; DraftPct=$c.DraftPct; Context=$c.Context; GraphsReuse=$c.GraphsReuse})
                if ($Watcher.History.Count -gt 30) { $Watcher.History.RemoveAt(0) }
            }
            $Watcher.Current = New-CurrentState
            $hadProgress = $false
        }
    }
    return $hadProgress
}

# ---------- discovery ----------
function Discover-Logs {
    if (-not (Test-Path $logDir)) { return @() }
    $cutoff = (Get-Date).AddHours(-24)
    Get-ChildItem -Path $logDir -Filter "*server_*.log" |
        Where-Object { $_.LastWriteTime -gt $cutoff } |
        Sort-Object LastWriteTime -Descending |
        Select-Object -ExpandProperty FullName
}

# ---------- startup ----------
Clear-Host
Write-Host "llama.cpp Dual GPU Log Monitor" -ForegroundColor Cyan
Write-Host "Log dir: $logDir" -ForegroundColor Gray
Write-Host ""

$found = Discover-Logs
if ($found.Count -eq 0) {
    Write-Host "No *server_*.log files found (past 24h). Waiting..." -ForegroundColor Red
}

foreach ($lp in $found) {
    $key = Split-Path $lp -Leaf
    $label = $key; if ($key -match '^(B\d+)') { $label = $Matches[1] }
    $alias = ""
    $head = Get-Content $lp -TotalCount 500 -ErrorAction SilentlyContinue
    foreach ($line in $head) {
        if ($line -match $patternModelAlias) { $alias = $Matches[1]; break }
    }

    $w = @{
        Path=$lp; LastSize=0; Current=New-CurrentState; RequestCount=0
        History=[System.Collections.ArrayList]::new(); Label=$label
        Alias=if($alias){$alias}else{$label}
    }
    Write-Host "  Seeding $label : $($w.Alias)..." -ForegroundColor Green
    Seed-Watcher -Watcher $w
    $watchers[$key] = $w
    Write-Host "    -> $($w.RequestCount) requests, $($w.History.Count) in history" -ForegroundColor DarkGray
}

Write-Host ""
Write-Host "Starting monitor... (Ctrl+C to stop)" -ForegroundColor DarkGray
Start-Sleep -Milliseconds 500

# ---------- main loop ----------
$running = $true

# Proper Ctrl+C handling
try {
    [Console]::TreatControlCAsInput = $false
    $null = Register-EngineEvent -SourceIdentifier PowerShell.Exiting -Action {}
}
catch { }

while ($running) {
    try {
        # Check for Ctrl+C via key poll (quick, doesn't block)
        if ([Console]::KeyAvailable) {
            $key = [Console]::ReadKey($true)
            if (($key.Key -eq "C" -and $key.Modifiers -eq "Control") -or $key.Key -eq "Escape") {
                $running = $false
                break
            }
        }

        # Discover new logs
        $currentLogs = Discover-Logs
        foreach ($lp in $currentLogs) {
            $k = Split-Path $lp -Leaf
            if (-not $watchers.ContainsKey($k)) {
                $label = $k; if ($k -match '^(B\d+)') { $label = $Matches[1] }
                $alias = ""
                $head = Get-Content $lp -TotalCount 200 -ErrorAction SilentlyContinue
                foreach ($line in $head) {
                    if ($line -match $patternModelAlias) { $alias = $Matches[1]; break }
                }
                $watchers[$k] = @{
                    Path=$lp; LastSize=0; Current=New-CurrentState; RequestCount=0
                    History=[System.Collections.ArrayList]::new(); Label=$label
                    Alias=if($alias){$alias}else{$label}
                }
                # Seed immediately so dashboard shows data
                Seed-Watcher -Watcher $watchers[$k]
            }
        }

        # Remove stale watchers
        $stale = @($watchers.Keys | Where-Object { -not (Test-Path $watchers[$_].Path) })
        foreach ($k in $stale) { $watchers.Remove($k) }

        # Process new content from each log
        foreach ($key in @($watchers.Keys | Sort-Object)) {
            Process-WatcherTail -Watcher $watchers[$key] | Out-Null
        }

        Show-Dashboard
    }
    catch {
        # Show error at bottom, continue
        Write-Host "`n  Error: $($_.Exception.Message.Substring(0, [math]::Min(80, $_.Exception.Message.Length)))" -ForegroundColor Red
    }
    Start-Sleep -Milliseconds $RefreshMs
}

# ---------- cleanup ----------
Clear-Host
Write-Host ""
Write-Host "Session Summary" -ForegroundColor Cyan
Write-Host "========================================"
foreach ($key in @($watchers.Keys | Sort-Object)) {
    Write-Host "  $($watchers[$key].Label): $($watchers[$key].RequestCount) requests ($($watchers[$key].Alias))" -ForegroundColor Yellow
}
Write-Host ""

