function New-CurrentState { return @{PromptTps=0; PromptTok=0; EvalTps=0; EvalTok=0; TotalTps=0; TotalTok=0; DraftPct=0; Context=0; GraphsReuse=0; HasPrompt=$false; HasEval=$false; LiveTg=0; LiveTokens=0; PromptProgPct=0; PromptProgTps=0} }

function Parse-FileIntoHistory {
