200	    $stream.Seek($Watcher.LastSize, 'Begin') | Out-Null
201	    $newContent = [System.IO.StreamReader]::new($stream).ReadToEnd()
202	    $stream.Close()
203	    $Watcher.LastSize = $sz
204	
205	    $c = $Watcher.Current; $had = $false
206	    foreach ($rawLine in ($newContent -split "`n")) {
207	        $rawLine = $rawLine.Trim()
208	        if ($rawLine -eq "") { continue }
209	        $p = Get-CleanLine $rawLine
210	        if ($p -eq "") { continue }
211	
