213	        if ($p -match $patternProgress) { $c.LiveTokens=[int]$Matches[1]; $c.LiveTg=[double]$Matches[2]; $had=$true; continue }
214	        if ($p -match $patternPromptProg) { $c.PromptProgPct=[double]$Matches[2]; $c.PromptProgTps=[double]$Matches[4]; $had=$true; continue }
215	
216	        if ($p -match $patternPrompt) { $c.PromptTok=[int]$Matches[2]; $c.PromptTps=[double]$Matches[4]; $c.HasPrompt=$true }
217	        elseif ($p -match $patternEval) { $c.EvalTok=[int]$Matches[2]; $c.EvalTps=[double]$Matches[4]; $c.HasEval=$true }
218	        elseif ($p -match $patternTotal) { $c.TotalTok=[int]$Matches[2]; $ms=[double]$Matches[1]; $c.TotalTps=if($ms -gt 0){$c.TotalTok/($ms/1000)}else{0} }
219	        elseif ($p -match $patternDraft) { $c.DraftPct=[double]$Matches[1] }
220	        elseif ($p -match $patternGraphs) { $c.GraphsReuse=[int]$Matches[1] }
221	        elseif ($p -match $patternRelease) {
222	            $c.Context=[int]$Matches[1]
223	            if ($c.HasPrompt -and $c.HasEval) {
224	                $Watcher.RequestCount++
225	                [void]$Watcher.History.Add([PSCustomObject]@{PromptTok=$c.PromptTok; PromptTps=$c.PromptTps; EvalTok=$c.EvalTok; EvalTps=$c.EvalTps; TotalTps=$c.TotalTps; DraftPct=$c.DraftPct; Context=$c.Context; GraphsReuse=$c.GraphsReuse})
226	                if ($Watcher.History.Count -gt 30) { $Watcher.History.RemoveAt(0) }
