270	while ($running) {
271	    try {
272	        if ([Console]::KeyAvailable) {
273	            $key = [Console]::ReadKey($true)
274	            if (($key.Key -eq "C" -and $key.Modifiers -eq "Control") -or $key.Key -eq "Escape") {
275	                $running = $false; break
276	            }
277	        }
