279	        # Detect log rotation: same GPU prefix, newer file
280	        $currentMap = Get-GPUToLogFile
281	        foreach ($gpu in $currentMap.Keys) {
282	            if ($currentMap[$gpu] -ne $watchers[$gpu].Path) {
283	                # Rotation detected
284	                $watchers[$gpu].Path = $currentMap[$gpu]
285	                $watchers[$gpu].LastSize = 0
286	                $watchers[$gpu].Current = New-CurrentState
287	            }
288	        }
289	
290	        # Process tails
291	        foreach ($gpu in @($watchers.Keys | Sort-Object)) {
292	            Process-Tail -Watcher $watchers[$gpu] | Out-Null
293	        }
