1	# llama-cpp-log-monitor.ps1 - Dual GPU (multi-log) Performance Monitor
2	param(
3	    [int]$RefreshMs = 500
4	)
5	
6	$logDir = "C:\llama.cpp-prod\logs"
7	
8	# ---------- regex patterns ----------
9	$patternPrompt     = 'prompt eval time\s*=\s*([\d.]+)\s*ms\s*/\s*(\d+)\s*tokens?\s*\(\s*([\d.]+)\s*ms per token,\s*([\d.]+)\s*tokens per second\)'
10	$patternEval       = 'eval time\s*=\s*([\d.]+)\s*ms\s*/\s*(\d+)\s*tokens?\s*\(\s*([\d.]+)\s*ms per token,\s*([\d.]+)\s*tokens per second\)'
11	$patternTotal      = 'total time\s*=\s*([\d.]+)\s*ms\s*/\s*(\d+)\s*tokens?'
12	$patternDraft      = 'draft acceptance\s*=\s*([\d.]+)'
13	$patternRelease    = 'stop processing:\s*n_tokens\s*=\s*(\d+)'
14	$patternGraphs     = 'graphs reused\s*=\s*(\d+)'
15	$patternProgress   = 'n_decoded\s*=\s*(\d+),\s*tg\s*=\s*([\d.]+)\s*t/s'
16	$patternPromptProg = 'prompt processing,\s*n_tokens\s*=\s*(\d+),\s*progress\s*=\s*([\d.]+),\s*t\s*=\s*([\d.]+)\s*s\s*/\s*([\d.]+)\s*tokens per second'
17	$patternModelAlias = "spawning server instance with name=([^\s]+) on port"
18	
19	function Get-CleanLine {
20	    param([string]$Line)
21	    $clean = $Line -replace '^\[\d+\]\s*', ''
22	    $clean = $clean -replace '^[\d.]+\s+[A-Z]\s+\w+\s+[^:]+\:\s*(?:id\s+\d+\s*\|\s*task\s+-?\d+\s*\|\s*)?', ''
23	    return $clean
24	}
25	
26	# ---------- discovery: one file per GPU (most recent) ----------
27	function Get-GPUToLogFile {
28	    # Returns hashtable: { "B50" => "C:\...\B50-server_2026-06-30_093631.log", "B70" => "..." }
29	    if (-not (Test-Path $logDir)) { return @{} }
30	    $cutoff = (Get-Date).AddHours(-24)
31	    $files = Get-ChildItem -Path $logDir -Filter "*server_*.log" |
32	        Where-Object { $_.LastWriteTime -gt $cutoff } |
33	        Sort-Object LastWriteTime -Descending
34	
35	    $result = @{}
36	    foreach ($f in $files) {
37	        $name = $f.Name
38	        # Extract GPU prefix: B50, B70, etc. from start of filename
39	        $prefix = ""
40	        if ($name -match '^(B\d+)') { $prefix = $Matches[1] }
41	        else { $prefix = $name }  # fallback: full filename
42	        if (-not $result.ContainsKey($prefix)) {
43	            $result[$prefix] = $f.FullName
44	        }
45	    }
46	    return $result
47	}
48	
49	# ---------- watcher state ----------
50	# Keyed by GPU prefix ("B50", "B70")
51	$watchers = @{}
52	
53	function New-CurrentState { return @{PromptTps=0; PromptTok=0; EvalTps=0; EvalTok=0; TotalTps=0; TotalTok=0; DraftPct=0; Context=0; GraphsReuse=0; HasPrompt=$false; HasEval=$false; LiveTg=0; LiveTokens=0; PromptProgPct=0; PromptProgTps=0} }
54	
55	function Parse-FileIntoHistory {
56	    param($Path, [ref]$Alias)
57	    $history = [System.Collections.ArrayList]::new()
58	    if (-not (Test-Path $Path)) { return $history }
59	
60	    # Extract alias from first 500 lines
61	    $head = Get-Content $Path -TotalCount 500 -ErrorAction SilentlyContinue
62	    foreach ($line in $head) {
63	        if ($line -match $patternModelAlias) { $Alias.Value = $Matches[1]; break }
64	    }
65	
66	    $c = New-CurrentState
67	    foreach ($rawLine in (Get-Content $Path -ReadCount 0)) {
68	        $rawLine = $rawLine.Trim()
69	        if ($rawLine -eq "") { continue }
70	        $payload = Get-CleanLine $rawLine
71	        if ($payload -eq "") { continue }
72	
73	        if ($payload -match $patternModelAlias) { $Alias.Value = $Matches[1]; continue }
74	        if ($payload -match $patternProgress -or $payload -match $patternPromptProg) { continue }
75	
76	        if ($payload -match $patternPrompt) {
77	            $c.PromptTok=[int]$Matches[2]; $c.PromptTps=[double]$Matches[4]; $c.HasPrompt=$true
78	        } elseif ($payload -match $patternEval) {
79	            $c.EvalTok=[int]$Matches[2]; $c.EvalTps=[double]$Matches[4]; $c.HasEval=$true
80	        } elseif ($payload -match $patternTotal) {
81	            $c.TotalTok=[int]$Matches[2]; $ms=[double]$Matches[1]; $c.TotalTps=if($ms -gt 0){$c.TotalTok/($ms/1000)}else{0}
82	        } elseif ($payload -match $patternDraft) { $c.DraftPct=[double]$Matches[1] }
83	        elseif ($payload -match $patternGraphs) { $c.GraphsReuse=[int]$Matches[1] }
84	        elseif ($payload -match $patternRelease) {
85	            $c.Context=[int]$Matches[1]
86	            if ($c.HasPrompt -and $c.HasEval) {
87	                [void]$history.Add([PSCustomObject]@{PromptTok=$c.PromptTok; PromptTps=$c.PromptTps; EvalTok=$c.EvalTok; EvalTps=$c.EvalTps; TotalTps=$c.TotalTps; DraftPct=$c.DraftPct; Context=$c.Context; GraphsReuse=$c.GraphsReuse})
88	            }
89	            $c=New-CurrentState
90	        }
91	    }
92	    return $history
93	}
94	
95	# ---------- dashboard ----------
96	function Show-Dashboard {
97	    $out = [System.Text.StringBuilder]::new()
98	    $ts = Get-Date -Format "yyyy-MM-dd HH:mm:ss"
99	    $nl = "`r`n"
100	
101	    [void]$out.Append("  llama.cpp Dual GPU Performance Monitor  |  $ts$nl")
102	    [void]$out.Append("  " + ("=" * 110) + $nl)
103	
104	    $keys = @($watchers.Keys | Sort-Object)
105	    if ($keys.Count -eq 0) {
106	        [void]$out.Append("$nl  No active logs found (past 24h).$nl")
107	        [void]$out.Append("  Looking in: $logDir$nl")
108	        [void]$out.Append("$nl  Waiting... (Ctrl+C to stop)$nl")
109	        Clear-Host
110	        Write-Host ($out.ToString())
111	        return
112	    }
113	
114	    # --- GPU panels side by side ---
115	    [void]$out.Append($nl)
116	    $panelW = 54
117	    $allPanels = @(); $maxLines = 0
118	
119	    foreach ($key in $keys) {
120	        $W = $watchers[$key]; $c = $W.Current; $h = $W.History
121	        $avgP = if ($h.Count -gt 0) { [math]::Round((($h | Measure-Object PromptTps -Average).Average),1) } else { 0 }
122	        $avgE = if ($h.Count -gt 0) { [math]::Round((($h | Measure-Object EvalTps -Average).Average),1) } else { 0 }
123	
124	        $pl = [System.Collections.ArrayList]::new()
125	        [void]$pl.Add("  $($W.Label)  [$($W.Alias)]")
126	        [void]$pl.Add("  " + ("-" * 48))
127	        [void]$pl.Add("  Requests: $($W.RequestCount)")
128	        [void]$pl.Add("")
129	        [void]$pl.Add("  Prompt:   $(if($c.HasPrompt){'{0,7} tok/s' -f [math]::Round($c.PromptTps,1)}else{'    ---'})   ($($c.PromptTok) tok)")
130	        [void]$pl.Add("  Output:   $(if($c.HasEval){'{0,7} tok/s' -f [math]::Round($c.EvalTps,1)}else{'    ---'})   ($($c.EvalTok) tok)")
131	        [void]$pl.Add("  Total:    {0,7} tok/s" -f [math]::Round($c.TotalTps,1))
132	        [void]$pl.Add("  Live tg:  $(if($c.LiveTg -gt 0){'{0,7} t/s' -f [math]::Round($c.LiveTg,1) + '   (' + $c.LiveTokens + ' tok)'}else{'    ---'})")
133	        [void]$pl.Add("  PP Eval:  $(if($c.PromptProgPct -gt 0){'{0,7}%' -f [math]::Round($c.PromptProgPct*100,0) + ' @ ' + [math]::Round($c.PromptProgTps,0) + ' t/s'}else{'    ---'})")
134	        [void]$pl.Add("  Draft:    $(if($c.DraftPct -gt 0){'{0,7}%' -f [math]::Round($c.DraftPct*100,1)}else{'    ---'})")
