# llama-cpp-log-monitor.ps1 - Dual GPU (multi-log) Performance Monitor
param(
    [int]$RefreshMs = 500
)

$logDir = "C:\llama.cpp-prod\logs"

# ---------- regex patterns ----------
$patternPrompt     = 'prompt eval time\s*=\s*([\d.]+)\s*ms\s*/\s*(\d+)\s*tokens?\s*\(\s*([\d.]+)\s*ms per token,\s*([\d.]+)\s*tokens per second\)'
$patternEval       = 'eval time\s*=\s*([\d.]+)\s*ms\s*/\s*(\d+)\s*tokens?\s*\(\s*([\d.]+)\s*ms per token,\s*([\d.]+)\s*tokens per second\)'
$patternTotal      = 'total time\s*=\s*([\d.]+)\s*ms\s*/\s*(\d+)\s*tokens?'
$patternDraft      = 'draft acceptance\s*=\s*([\d.]+)'
$patternRelease    = 'stop processing:\s*n_tokens\s*=\s*(\d+)'
$patternGraphs     = 'graphs reused\s*=\s*(\d+)'
$patternProgress   = 'n_decoded\s*=\s*(\d+),\s*tg\s*=\s*([\d.]+)\s*t/s'
$patternPromptProg = 'prompt processing,\s*n_tokens\s*=\s*(\d+),\s*progress\s*=\s*([\d.]+),\s*t\s*=\s*([\d.]+)\s*s\s*/\s*([\d.]+)\s*tokens per second'
$patternModelAlias = "spawning server instance with name=([^\s]+) on port"

function Get-CleanLine {
    param([string]$Line)
    $clean = $Line -replace '^\[\d+\]\s*', ''
    $clean = $clean -replace '^[\d.]+\s+[A-Z]\s+\w+\s+[^:]+\:\s*(?:id\s+\d+\s*\|\s*task\s+-?\d+\s*\|\s*)?', ''
    return $clean
}

# ---------- discovery: one file per GPU (most recent) ----------
function Get-GPUToLogFile {
    # Returns hashtable: { "B50" => "C:\...\B50-server_2026-06-30_093631.log", "B70" => "..." }
    if (-not (Test-Path $logDir)) { return @{} }
    $cutoff = (Get-Date).AddHours(-24)
    $files = Get-ChildItem -Path $logDir -Filter "*server_*.log" |
        Where-Object { $_.LastWriteTime -gt $cutoff } |
        Sort-Object LastWriteTime -Descending

    $result = @{}
    foreach ($f in $files) {
        $name = $f.Name
        # Extract GPU prefix: B50, B70, etc. from start of filename
        $prefix = ""
        if ($name -match '^(B\d+)') { $prefix = $Matches[1] }
        else { $prefix = $name }  # fallback: full filename
        if (-not $result.ContainsKey($prefix)) {
            $result[$prefix] = $f.FullName
        }
    }
    return $result
}

# ---------- watcher state ----------
# Keyed by GPU prefix ("B50", "B70")
$watchers = @{}

function New-CurrentState { return @{PromptTps=0; PromptTok=0; EvalTps=0; EvalTok=0; TotalTps=0; TotalTok=0; DraftPct=0; Context=0; GraphsReuse=0; HasPrompt=$false; HasEval=$false; LiveTg=0; LiveTokens=0; PromptProgPct=0; PromptProgTps=0} }

function Parse-FileIntoHistory {
    param($Path, [ref]$Alias)
    $history = [System.Collections.ArrayList]::new()
    if (-not (Test-Path $Path)) { return $history }

    # Extract alias from first 500 lines
    $head = Get-Content $Path -TotalCount 500 -ErrorAction SilentlyContinue
    foreach ($line in $head) {
        if ($line -match $patternModelAlias) { $Alias.Value = $Matches[1]; break }
    }

    $c = New-CurrentState
    foreach ($rawLine in (Get-Content $Path -ReadCount 0)) {
        $rawLine = $rawLine.Trim()
        if ($rawLine -eq "") { continue }
        $payload = Get-CleanLine $rawLine
        if ($payload -eq "") { continue }

        if ($payload -match $patternModelAlias) { $Alias.Value = $Matches[1]; continue }
        if ($payload -match $patternProgress -or $payload -match $patternPromptProg) { continue }

        if ($payload -match $patternPrompt) {
            $c.PromptTok=[int]$Matches[2]; $c.PromptTps=[double]$Matches[4]; $c.HasPrompt=$true
        } elseif ($payload -match $patternEval) {
            $c.EvalTok=[int]$Matches[2]; $c.EvalTps=[double]$Matches[4]; $c.HasEval=$true
        } elseif ($payload -match $patternTotal) {
            $c.TotalTok=[int]$Matches[2]; $ms=[double]$Matches[1]; $c.TotalTps=if($ms -gt 0){$c.TotalTok/($ms/1000)}else{0}
        } elseif ($payload -match $patternDraft) { $c.DraftPct=[double]$Matches[1] }
        elseif ($payload -match $patternGraphs) { $c.GraphsReuse=[int]$Matches[1] }
        elseif ($payload -match $patternRelease) {
            $c.Context=[int]$Matches[1]
            if ($c.HasPrompt -and $c.HasEval) {
                [void]$history.Add([PSCustomObject]@{PromptTok=$c.PromptTok; PromptTps=$c.PromptTps; EvalTok=$c.EvalTok; EvalTps=$c.EvalTps; TotalTps=$c.TotalTps; DraftPct=$c.DraftPct; Context=$c.Context; GraphsReuse=$c.GraphsReuse})
            }
            $c=New-CurrentState
        }
    }
    return $history
}

# ---------- dashboard ----------
function Show-Dashboard {
    $out = [System.Text.StringBuilder]::new()
    $ts = Get-Date -Format "yyyy-MM-dd HH:mm:ss"
    $nl = "`r`n"

    [void]$out.Append("  llama.cpp Dual GPU Performance Monitor  |  $ts$nl")
    [void]$out.Append("  " + ("=" * 110) + $nl)

    $keys = @($watchers.Keys | Sort-Object)
    if ($keys.Count -eq 0) {
        [void]$out.Append("$nl  No active logs found (past 24h).$nl")
        [void]$out.Append("  Looking in: $logDir$nl")
        [void]$out.Append("$nl  Waiting... (Ctrl+C to stop)$nl")
        Clear-Host
        Write-Host ($out.ToString())
        return
    }

    # --- GPU panels side by side ---
    [void]$out.Append($nl)
    $panelW = 54
    $allPanels = @(); $maxLines = 0

    foreach ($key in $keys) {
        $W = $watchers[$key]; $c = $W.Current; $h = $W.History
        $avgP = if ($h.Count -gt 0) { [math]::Round((($h | Measure-Object PromptTps -Average).Average),1) } else { 0 }
        $avgE = if ($h.Count -gt 0) { [math]::Round((($h | Measure-Object EvalTps -Average).Average),1) } else { 0 }

        $pl = [System.Collections.ArrayList]::new()
        [void]$pl.Add("  $($W.Label)  [$($W.Alias)]")
        [void]$pl.Add("  " + ("-" * 48))
        [void]$pl.Add("  Requests: $($W.RequestCount)")
        [void]$pl.Add("")
        [void]$pl.Add("  Prompt:   $(if($c.HasPrompt){'{0,7} tok/s' -f [math]::Round($c.PromptTps,1)}else{'    ---'})   ($($c.PromptTok) tok)")
        [void]$pl.Add("  Output:   $(if($c.HasEval){'{0,7} tok/s' -f [math]::Round($c.EvalTps,1)}else{'    ---'})   ($($c.EvalTok) tok)")
        [void]$pl.Add("  Total:    {0,7} tok/s" -f [math]::Round($c.TotalTps,1))
        [void]$pl.Add("  Live tg:  $(if($c.LiveTg -gt 0){'{0,7} t/s' -f [math]::Round($c.LiveTg,1) + '   (' + $c.LiveTokens + ' tok)'}else{'    ---'})")
        [void]$pl.Add("  PP Eval:  $(if($c.PromptProgPct -gt 0){'{0,7}%' -f [math]::Round($c.PromptProgPct*100,0) + ' @ ' + [math]::Round($c.PromptProgTps,0) + ' t/s'}else{'    ---'})")
        [void]$pl.Add("  Draft:    $(if($c.DraftPct -gt 0){'{0,7}%' -f [math]::Round($c.DraftPct*100,1)}else{'    ---'})")
        [void]$pl.Add("  Graphs:   $(if($c.GraphsReuse -gt 0){$c.GraphsReuse}else{'---'})")
        [void]$pl.Add("")
        [void]$pl.Add("  Session avg:")
        [void]$pl.Add("    Prompt: $avgP t/s  |  Output: $avgE t/s")

        $allPanels += ,$pl
        if ($pl.Count -gt $maxLines) { $maxLines = $pl.Count }
    }

    for ($i = 0; $i -lt $maxLines; $i++) {
        $row = ""
        foreach ($panel in $allPanels) {
            $txt = if ($i -lt $panel.Count) { $panel[$i] } else { "" }
            $row += $txt.PadRight($panelW)
        }
        [void]$out.Append($row + $nl)
    }

    # --- Per-GPU recent requests (stacked vertically) ---
    [void]$out.Append($nl)
    [void]$out.Append("  RECENT REQUESTS (per GPU)$nl")
    [void]$out.Append("  " + ("-" * 108) + $nl)

    $perGPU = 10
    # Exact format: each field width chosen to align with header
    $rowFmt = "  {0,2}  {1,6}  {2,7}  {3,6}  {4,7}  {5,9}   {6,6}  {7,6}  {8,8}"

    foreach ($key in $keys) {
        $W = $watchers[$key]
        [void]$out.Append("  -- $($W.Label) --$nl")
        [void]$out.Append(($rowFmt -f "#", "Prompt", "P-t/s", "Eval", "E-t/s", "Total-t/s", "Draft", "Graphs", "Context") + $nl)

        $start = [math]::Max(0, $W.History.Count - $perGPU)
        $n = 1
        for ($j = $start; $j -lt $W.History.Count; $j++) {
            $h = $W.History[$j]
            $dS = if ($h.DraftPct -gt 0) { "$([math]::Round($h.DraftPct*100,1))%" } else { "---" }
            $gS = if ($h.GraphsReuse -gt 0) { $h.GraphsReuse.ToString("N0") } else { "---" }
            $ctx = if ($h.Context) { $h.Context.ToString("N0") } else { "---" }
            [void]$out.Append(($rowFmt -f $n, $h.PromptTok, [math]::Round($h.PromptTps,1), $h.EvalTok, [math]::Round($h.EvalTps,1), [math]::Round($h.TotalTps,1), $dS, $gS, $ctx) + $nl)
            $n++
        }
        [void]$out.Append($nl)
    }

    # Pad to screen height, then render
    $screenH = $Host.UI.RawUI.WindowSize.Height
    $lines = ($out.ToString() -split "`n").Count
    for ($i = $lines; $i -lt $screenH - 1; $i++) { [void]$out.Append($nl) }

    Clear-Host
    Write-Host ($out.ToString())
}

# ---------- tail ----------
function Process-Tail {
    param($Watcher)
    $fi = Get-Item $Watcher.Path -ErrorAction SilentlyContinue
    if (-not $fi) { return $false }
    $sz = $fi.Length
    if ($sz -eq $Watcher.LastSize) { return $false }
    if ($sz -lt $Watcher.LastSize) { $Watcher.LastSize = 0 }

    $stream = [System.IO.FileStream]::new($Watcher.Path, 'Open', 'Read', 'ReadWrite')
    $stream.Seek($Watcher.LastSize, 'Begin') | Out-Null
    $newContent = [System.IO.StreamReader]::new($stream).ReadToEnd()
    $stream.Close()
    $Watcher.LastSize = $sz

    $c = $Watcher.Current; $had = $false
    foreach ($rawLine in ($newContent -split "`n")) {
        $rawLine = $rawLine.Trim()
        if ($rawLine -eq "") { continue }
        $p = Get-CleanLine $rawLine
        if ($p -eq "") { continue }

        if ($p -match $patternModelAlias) { $Watcher.Alias = $Matches[1]; continue }
        if ($p -match $patternProgress) { $c.LiveTokens=[int]$Matches[1]; $c.LiveTg=[double]$Matches[2]; $had=$true; continue }
        if ($p -match $patternPromptProg) { $c.PromptProgPct=[double]$Matches[2]; $c.PromptProgTps=[double]$Matches[4]; $had=$true; continue }

        if ($p -match $patternPrompt) { $c.PromptTok=[int]$Matches[2]; $c.PromptTps=[double]$Matches[4]; $c.HasPrompt=$true }
        elseif ($p -match $patternEval) { $c.EvalTok=[int]$Matches[2]; $c.EvalTps=[double]$Matches[4]; $c.HasEval=$true }
        elseif ($p -match $patternTotal) { $c.TotalTok=[int]$Matches[2]; $ms=[double]$Matches[1]; $c.TotalTps=if($ms -gt 0){$c.TotalTok/($ms/1000)}else{0} }
        elseif ($p -match $patternDraft) { $c.DraftPct=[double]$Matches[1] }
        elseif ($p -match $patternGraphs) { $c.GraphsReuse=[int]$Matches[1] }
        elseif ($p -match $patternRelease) {
            $c.Context=[int]$Matches[1]
            if ($c.HasPrompt -and $c.HasEval) {
                $Watcher.RequestCount++
                [void]$Watcher.History.Add([PSCustomObject]@{PromptTok=$c.PromptTok; PromptTps=$c.PromptTps; EvalTok=$c.EvalTok; EvalTps=$c.EvalTps; TotalTps=$c.TotalTps; DraftPct=$c.DraftPct; Context=$c.Context; GraphsReuse=$c.GraphsReuse})
                if ($Watcher.History.Count -gt 30) { $Watcher.History.RemoveAt(0) }
            }
            $Watcher.Current=New-CurrentState; $had=$false
        }
    }
    return $had
}

# ---------- startup ----------
Clear-Host
Write-Host "llama.cpp Dual GPU Log Monitor" -ForegroundColor Cyan
Write-Host "Log dir: $logDir" -ForegroundColor Gray
Write-Host ""

$gpuMap = Get-GPUToLogFile
if ($gpuMap.Count -eq 0) {
    Write-Host "No *server_*.log files found (past 24h). Waiting..." -ForegroundColor Red
}

foreach ($gpu in ($gpuMap.Keys | Sort-Object)) {
    $path = $gpuMap[$gpu]
    $aliasRef = [ref]""
    $history = Parse-FileIntoHistory -Path $path -Alias $aliasRef
    $alias = if ($aliasRef.Value) { $aliasRef.Value } else { $gpu }

    $watchers[$gpu] = @{
        Path         = $path
        Label        = $gpu
        Alias        = $alias
        LastSize     = (Get-Item $path | Select-Object -ExpandProperty Length)
        Current      = New-CurrentState
        History      = $history
        RequestCount = $history.Count
    }
    Write-Host "  $gpu : $alias ($($history.Count) requests)" -ForegroundColor Green
}

Write-Host ""
Write-Host "Starting monitor... (Ctrl+C to stop)" -ForegroundColor DarkGray
Start-Sleep -Milliseconds 500

# ---------- main loop ----------
$running = $true

while ($running) {
    try {
        if ([Console]::KeyAvailable) {
            $key = [Console]::ReadKey($true)
            if (($key.Key -eq "C" -and $key.Modifiers -eq "Control") -or $key.Key -eq "Escape") {
                $running = $false; break
            }
        }

        # Detect log rotation: same GPU prefix, newer file
        $currentMap = Get-GPUToLogFile
        foreach ($gpu in $currentMap.Keys) {
            if ($currentMap[$gpu] -ne $watchers[$gpu].Path) {
                # Rotation detected
                $watchers[$gpu].Path = $currentMap[$gpu]
                $watchers[$gpu].LastSize = 0
                $watchers[$gpu].Current = New-CurrentState
            }
        }

        # Process tails
        foreach ($gpu in @($watchers.Keys | Sort-Object)) {
            Process-Tail -Watcher $watchers[$gpu] | Out-Null
        }

        Show-Dashboard
    } catch {
        # continue
    }
    Start-Sleep -Milliseconds $RefreshMs
}

# ---------- cleanup ----------
Clear-Host
Write-Host ""
Write-Host "Session Summary" -ForegroundColor Cyan
Write-Host "========================================"
foreach ($gpu in @($watchers.Keys | Sort-Object)) {
    Write-Host "  $gpu : $($watchers[$gpu].RequestCount) requests ($($watchers[$gpu].Alias))" -ForegroundColor Yellow
}
Write-Host ""

